import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Language = 'English' | 'Arabic';
export type AgeGroup = '3-4' | '4-6' | '7-9' | '9-12';
export type StoryLength = 'Short' | 'Medium';
export type ArtStyle = 'Cute Cartoon' | 'Storybook Watercolor' | 'Pixar-like 3D' | 'Soft Pastel Illustration';

export interface StoryParams {
  idea: string;
  language: Language;
  ageGroup: AgeGroup;
  length: StoryLength;
  artStyle: ArtStyle;
}

export interface Character {
  name: string;
  description: string;
  personality: string;
}

export interface StoryPage {
  page: number;
  text: string;
  image_prompt: string;
  generatedImage?: string; // base64 data
  isGeneratingImage?: boolean;
}

export interface StoryData {
  story_info: {
    title: string;
    language: string;
    age_group: string;
    art_style: string;
  };
  characters: Character[];
  pages: StoryPage[];
}

export interface StoryState {
  step: 'setup' | 'generating_story' | 'reading';
  params: StoryParams;
  data: StoryData | null;
  error: string | null;
}

import { AgeGroup, ArtStyle, StoryLength } from "./types";

export const AGE_GROUPS: AgeGroup[] = ['3-4', '4-6', '7-9', '9-12'];
export const STORY_LENGTHS: StoryLength[] = ['Short', 'Medium'];
export const ART_STYLES: ArtStyle[] = [
  'Cute Cartoon', 
  'Storybook Watercolor', 
  'Pixar-like 3D', 
  'Soft Pastel Illustration'
];

export const INITIAL_STORY_PARAMS = {
  idea: '',
  language: 'English' as const,
  ageGroup: '4-6' as const,
  length: 'Short' as const,
  artStyle: 'Cute Cartoon' as const,
};

// Prompt templates
export const SYSTEM_INSTRUCTION = `You are "Sawan Kids Story Studio", a professional children's story creation engine. 
Your goal is to generate safe, educational, and engaging stories for children.

STRICT OUTPUT FORMAT:
You must return a single valid JSON object. Do not include markdown code blocks (like \`\`\`json). 
The JSON must strictly follow this schema:

{
  "story_info": {
    "title": "Story Title",
    "language": "English or Arabic",
    "age_group": "Target Age",
    "art_style": "Chosen Art Style"
  },
  "characters": [
    {
      "name": "Character Name",
      "description": "Visual description consistent for image generation",
      "personality": "Personality traits"
    }
  ],
  "pages": [
    {
      "page": 1,
      "text": "Story text for this page",
      "image_prompt": "Detailed image generation prompt"
    }
  ]
}

CONTENT RULES:
1. Language: If Arabic is selected, use simple, child-friendly Arabic suitable for the age group.
2. Safety: No violence, no scary elements, warm positive emotions.
3. Consistency: Character descriptions in image prompts must be consistent across all pages.
4. Image Prompts: Must be very detailed, including character appearance, environment, mood, lighting, camera angle, and the chosen art style.
`;

import { GoogleGenAI, Type } from "@google/genai";
import { StoryData, StoryParams } from "../types";
import { SYSTEM_INSTRUCTION } from "../constants";

// Helper to get client with key
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found. Please check your environment variables.");
  }
  return new GoogleGenAI({ apiKey });
};

export const generateStoryStructure = async (params: StoryParams): Promise<StoryData> => {
  const ai = getClient();

  const prompt = `
    Create a children's story based on the following inputs:
    1. Story Idea: ${params.idea}
    2. Language: ${params.language}
    3. Age Group: ${params.ageGroup}
    4. Length: ${params.length} (Short = 6 pages, Medium = 12 pages)
    5. Art Style: ${params.artStyle}

    Follow all quality rules and strict JSON output format defined in the system instructions.
  `;

  // We use gemini-3-flash-preview for fast, high-quality text generation and JSON adherence
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: 'application/json',
      // We can use a schema, but the prompt is strict enough usually. 
      // Let's add schema to be safe given the detailed requirement.
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          story_info: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              language: { type: Type.STRING },
              age_group: { type: Type.STRING },
              art_style: { type: Type.STRING },
            },
            required: ["title", "language", "age_group", "art_style"]
          },
          characters: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                description: { type: Type.STRING },
                personality: { type: Type.STRING },
              },
              required: ["name", "description", "personality"]
            }
          },
          pages: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                page: { type: Type.INTEGER },
                text: { type: Type.STRING },
                image_prompt: { type: Type.STRING },
              },
              required: ["page", "text", "image_prompt"]
            }
          }
        },
        required: ["story_info", "characters", "pages"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");

  try {
    // Sometimes models add markdown blocks despite MIME type
    const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanedText) as StoryData;
  } catch (e) {
    console.error("Failed to parse story JSON", text);
    throw new Error("Failed to generate valid story structure.");
  }
};

export const generateIllustration = async (prompt: string): Promise<string> => {
  const ai = getClient();

  // Using gemini-2.5-flash-image for reliable, key-based generation without OAuth complexity in this demo.
  // Ideally, for a "Pro" app, we would use gemini-3-pro-image-preview, but that requires user-selected keys.
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: prompt,
    config: {
       // Only aspect ratio is strictly supported on flash-image generally, mimeType not always needed but good practice.
       // Note: responseMimeType is NOT supported for nano banana series (flash-image) per guidelines.
    }
  });

  // Extract image
  // The output response may contain both image and text parts; you must iterate through all parts to find the image part.
  const candidates = response.candidates;
  if (candidates && candidates.length > 0 && candidates[0].content && candidates[0].content.parts) {
      for (const part of candidates[0].content.parts) {
          if (part.inlineData && part.inlineData.data) {
              return part.inlineData.data; // Base64 string
          }
      }
  }

  throw new Error("No image generated.");
};

export const regeneratePrompt = async (currentPrompt: string): Promise<string> => {
    const ai = getClient();
    // Simple text task to rewrite the prompt
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Rewrite the following image prompt to change the camera angle or composition slightly, while keeping the subject and style exactly the same. 

        Original Prompt: "${currentPrompt}"

        Return ONLY the new prompt text.`,
    });

    return response.text?.trim() || currentPrompt;
}

