export default SetupForm;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, ArrowRight, RefreshCw, Download, Home, Wand2 } from 'lucide-react';
import { StoryData, StoryPage } from '../types';
import { generateIllustration, regeneratePrompt } from '../services/gemini';

interface StoryBookProps {
  story: StoryData;
  onReset: () => void;
}

const StoryBook: React.FC<StoryBookProps> = ({ story, onReset }) => {
  const [currentPageIndex, setCurrentPageIndex] = useState(0);
  const [pages, setPages] = useState<StoryPage[]>(story.pages);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);

  const isRTL = story.story_info.language === 'Arabic';
  const currentPage = pages[currentPageIndex];

  // Auto-generate image for the current page if missing
  useEffect(() => {
    const generateForPage = async () => {
      if (!currentPage.generatedImage && !currentPage.isGeneratingImage) {

        // Mark as generating
        setPages(prev => prev.map((p, idx) => 
          idx === currentPageIndex ? { ...p, isGeneratingImage: true } : p
        ));

        try {
          // Construct a full prompt using character info for consistency
          const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
          ).join(' ');

          const fullPrompt = `Art Style: ${story.story_info.art_style}. ${characterContext} Scene: ${currentPage.image_prompt}`;

          const base64Image = await generateIllustration(fullPrompt);

          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
          ));

        } catch (error) {
          console.error("Failed to generate image", error);
          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
          ));
        }
      }
    };

    generateForPage();
  }, [currentPageIndex, currentPage.generatedImage, currentPage.isGeneratingImage, currentPage.image_prompt, story.characters, story.story_info.art_style]);

  const handleNext = () => {
    if (currentPageIndex < pages.length - 1) {
      setCurrentPageIndex(prev => prev + 1);
    }
  };

  const handlePrev = () => {
    if (currentPageIndex > 0) {
      setCurrentPageIndex(prev => prev - 1);
    }
  };

  const handleRegenerateImage = async () => {
    if (isGeneratingImage) return;
    setIsGeneratingImage(true);

    // Clear current image and mark generating
    setPages(prev => prev.map((p, idx) => 
        idx === currentPageIndex ? { ...p, generatedImage: undefined, isGeneratingImage: true } : p
    ));

    try {
        // Step 1: Rewrite prompt
        const newPrompt = await regeneratePrompt(currentPage.image_prompt);

        // Update prompt in state (optional, but good for debugging)
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, image_prompt: newPrompt } : p
        ));

        // Step 2: Generate new image
        const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
        ).join(' ');
        const fullPrompt = `Art Style: ${story.story_info.art_style}. ${characterContext} Scene: ${newPrompt}`;

        const base64Image = await generateIllustration(fullPrompt);

        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
        ));

    } catch (e) {
        console.error("Regeneration failed", e);
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
        ));
    } finally {
        setIsGeneratingImage(false);
    }
  };

  return (
    <div className="flex flex-col h-screen max-h-screen bg-paper overflow-hidden">
      {/* Header */}
      <header className="flex items-center justify-between p-4 bg-white shadow-sm border-b border-brand-100 z-20">
        <button onClick={onReset} className="flex items-center text-gray-500 hover:text-brand-600 transition-colors font-bold">
          <Home className="w-5 h-5 mr-2" />
          Home
        </button>
        <h1 className={`text-xl md:text-2xl font-heading font-bold text-brand-800 truncate px-4 ${isRTL ? 'font-arabic' : ''}`}>
          {story.story_info.title}
        </h1>
        <div className="w-20"></div> {/* Spacer for balance */}
      </header>

      {/* Main Content Area */}
      <main className="flex-1 flex items-center justify-center p-4 md:p-8 overflow-y-auto">
        <div className="w-full max-w-6xl aspect-[4/3] md:aspect-[2/1] bg-white rounded-2xl shadow-2xl flex flex-col md:flex-row overflow-hidden border border-gray-100 relative">

          {/* Text Side */}
          <div className={`flex-1 p-8 md:p-12 flex flex-col justify-center items-start ${isRTL ? 'order-2 text-right' : 'order-1 text-left'} bg-white overflow-y-auto z-10`}>
            <div className="w-full h-full flex flex-col justify-center">
                <span className="text-brand-300 font-heading font-bold text-6xl opacity-20 mb-4 select-none">
                    {currentPage.page}
                </span>
                <p className={`text-2xl md:text-3xl leading-relaxed text-gray-800 font-medium ${isRTL ? 'font-arabic' : 'font-heading'}`} dir={isRTL ? 'rtl' : 'ltr'}>
                {currentPage.text}
                </p>
            </div>
          </div>

          {/* Image Side */}
          <div className={`flex-1 relative bg-brand-50 flex items-center justify-center ${isRTL ? 'order-1' : 'order-2'}`}>
            {currentPage.generatedImage ? (
                <>
                    <img 
                        src={`data:image/jpeg;base64,${currentPage.generatedImage}`} 
                        alt={currentPage.image_prompt}
                        className="w-full h-full object-cover"
                    />
                    <div className="absolute top-4 right-4">
                        <button 
                            onClick={handleRegenerateImage}
                            disabled={currentPage.isGeneratingImage}
                            className="bg-white/80 hover:bg-white backdrop-blur-sm p-2 rounded-full shadow-lg text-brand-600 hover:text-brand-800 transition-all"
                            title="Regenerate Image"
                        >
                            <RefreshCw className={`w-5 h-5 ${currentPage.isGeneratingImage ? 'animate-spin' : ''}`} />
                        </button>
                    </div>
                </>
            ) : (
                <div className="flex flex-col items-center p-8 text-center animate-pulse">
                    <Wand2 className="w-16 h-16 text-brand-300 mb-4 animate-bounce" />
                    <p className="text-brand-400 font-heading text-lg">Painting this page...</p>
                    <p className="text-brand-300 text-sm mt-2 max-w-xs">{currentPage.image_prompt.substring(0, 100)}...</p>
                </div>
            )}
          </div>

        </div>
      </main>

      {/* Footer Navigation */}
      <footer className="p-6 bg-white border-t border-brand-100 flex items-center justify-between z-20">
        <button 
            onClick={handlePrev} 
            disabled={currentPageIndex === 0}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === 0 
                ? 'text-gray-300 cursor-not-allowed' 
                : 'bg-brand-100 text-brand-700 hover:bg-brand-200'
            }`}
        >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Previous
        </button>

        <div className="flex gap-2">
            {pages.map((_, idx) => (
                <div 
                    key={idx}
                    className={`w-3 h-3 rounded-full transition-all ${
                        idx === currentPageIndex ? 'bg-brand-500 scale-125' : 'bg-gray-200'
                    }`}
                />
            ))}
        </div>

        <button 
            onClick={handleNext} 
            disabled={currentPageIndex === pages.length - 1}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === pages.length - 1 
                ? 'text-gray-300 cursor-not-allowed' 
                : 'bg-brand-500 text-white hover:bg-brand-600 shadow-lg'
            }`}
        >
            Next
            <ArrowRight className="w-5 h-5 ml-2" />
        </button>
      </footer>
    </div>
  );
};

export default StoryBook;

import React, { useState } from 'react';
import { StoryData, StoryParams, StoryState } from './types';
import { INITIAL_STORY_PARAMS } from './constants';
import { generateStoryStructure } from './services/gemini';
import SetupForm from './components/SetupForm';
import StoryBook from './components/StoryBook';

const App: React.FC = () => {
  const [state, setState] = useState<StoryState>({
    step: 'setup',
    params: INITIAL_STORY_PARAMS,
    data: null,
    error: null,
  });

  const [isLoading, setIsLoading] = useState(false);

  const handleParamsChange = (newParams: StoryParams) => {
    setState(prev => ({ ...prev, params: newParams }));
  };

  const handleCreateStory = async () => {
    setIsLoading(true);
    setState(prev => ({ ...prev, error: null }));

    try {
      const storyData = await generateStoryStructure(state.params);
      setState(prev => ({
        ...prev,
        step: 'reading',
        data: storyData
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({
        ...prev,
        error: "Oops! We couldn't create the story right now. Please try again."
      }));
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setState({
      step: 'setup',
      params: INITIAL_STORY_PARAMS,
      data: null,
      error: null
    });
  };

  return (
    <div className="min-h-screen bg-brand-50 flex flex-col font-sans">
      {state.step === 'setup' && (
        <div className="flex-1 flex flex-col items-center justify-center p-4">
          <SetupForm 
            params={state.params} 
            onChange={handleParamsChange} 
            onSubmit={handleCreateStory}
            isLoading={isLoading}
          />
          {state.error && (
            <div className="mt-4 p-4 bg-red-100 text-red-700 rounded-xl border border-red-200">
              {state.error}
            </div>
          )}
        </div>
      )}

      {state.step === 'reading' && state.data && (
        <StoryBook story={state.data} onReset={handleReset} />
      )}
    </div>
  );
};

export default App;

export type Language = 'English' | 'Arabic';
export type AgeGroup = '3-4' | '4-6' | '7-9' | '9-12';
export type StoryLength = 'Short' | 'Medium';
export type ArtStyle = 'Cute Cartoon' | 'Storybook Watercolor' | 'Pixar-like 3D' | 'Soft Pastel Illustration';

export interface StoryParams {
  idea: string;
  language: Language;
  ageGroup: AgeGroup;
  length: StoryLength;
  artStyle: ArtStyle;
}

export interface Character {
  name: string;
  description: string;
  personality: string;
  age: string | number;
  gender: string;
}

export interface StoryPage {
  page: number;
  text: string;
  image_prompt: string;
  generatedImage?: string; // base64 data
  isGeneratingImage?: boolean;
}

export interface StoryData {
  story_info: {
    title: string;
    language: string;
    age_group: string;
    art_style: string;
  };
  characters: Character[];
  pages: StoryPage[];
}

export interface StoryState {
  step: 'setup' | 'generating_story' | 'reading';
  params: StoryParams;
  data: StoryData | null;
  error: string | null;
}

import { AgeGroup, ArtStyle, StoryLength } from "./types";

export const AGE_GROUPS: AgeGroup[] = ['3-4', '4-6', '7-9', '9-12'];
export const STORY_LENGTHS: StoryLength[] = ['Short', 'Medium'];
export const ART_STYLES: ArtStyle[] = [
  'Cute Cartoon', 
  'Storybook Watercolor', 
  'Pixar-like 3D', 
  'Soft Pastel Illustration'
];

export const INITIAL_STORY_PARAMS = {
  idea: '',
  language: 'English' as const,
  ageGroup: '4-6' as const,
  length: 'Short' as const,
  artStyle: 'Cute Cartoon' as const,
};

// Prompt templates
export const SYSTEM_INSTRUCTION = `You are "Sawan Kids Story Studio", a professional children's story creation engine. 
Your goal is to generate safe, educational, and engaging stories for children.

STRICT OUTPUT FORMAT:
You must return a single valid JSON object. Do not include markdown code blocks (like \`\`\`json). 
The JSON must strictly follow this schema:

{
  "story_info": {
    "title": "Story Title",
    "language": "English or Arabic",
    "age_group": "Target Age",
    "art_style": "Chosen Art Style"
  },
  "characters": [
    {
      "name": "Character Name",
      "description": "Visual description consistent for image generation",
      "personality": "Personality traits",
      "age": "Character Age (e.g. 5)",
      "gender": "Character Gender (e.g. Boy, Girl, Neutral)"
    }
  ],
  "pages": [
    {
      "page": 1,
      "text": "Story text for this page",
      "image_prompt": "Detailed image generation prompt"
    }
  ]
}

CONTENT RULES:
1. Language: If Arabic is selected, use simple, child-friendly Arabic suitable for the age group.
2. Safety: No violence, no scary elements, warm positive emotions.
3. Consistency: Character descriptions in image prompts must be consistent across all pages.
4. Image Prompts: Must be very detailed, including character appearance, environment, mood, lighting, camera angle, and the chosen art style.
`;

import { GoogleGenAI, Type } from "@google/genai";
import { StoryData, StoryParams } from "../types";
import { SYSTEM_INSTRUCTION } from "../constants";

// Helper to get client with key
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found. Please check your environment variables.");
  }
  return new GoogleGenAI({ apiKey });
};

export const generateStoryStructure = async (params: StoryParams): Promise<StoryData> => {
  const ai = getClient();

  const prompt = `
    Create a children's story based on the following inputs:
    1. Story Idea: ${params.idea}
    2. Language: ${params.language}
    3. Age Group: ${params.ageGroup}
    4. Length: ${params.length} (Short = 6 pages, Medium = 12 pages)
    5. Art Style: ${params.artStyle}

    Follow all quality rules and strict JSON output format defined in the system instructions.
  `;

  // We use gemini-3-flash-preview for fast, high-quality text generation and JSON adherence
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: 'application/json',
      // We can use a schema, but the prompt is strict enough usually. 
      // Let's add schema to be safe given the detailed requirement.
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          story_info: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              language: { type: Type.STRING },
              age_group: { type: Type.STRING },
              art_style: { type: Type.STRING },
            },
            required: ["title", "language", "age_group", "art_style"]
          },
          characters: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                description: { type: Type.STRING },
                personality: { type: Type.STRING },
                age: { type: Type.STRING },
                gender: { type: Type.STRING },
              },
              required: ["name", "description", "personality", "age", "gender"]
            }
          },
          pages: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                page: { type: Type.INTEGER },
                text: { type: Type.STRING },
                image_prompt: { type: Type.STRING },
              },
              required: ["page", "text", "image_prompt"]
            }
          }
        },
        required: ["story_info", "characters", "pages"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");

  try {
    // Sometimes models add markdown blocks despite MIME type
    const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanedText) as StoryData;
  } catch (e) {
    console.error("Failed to parse story JSON", text);
    throw new Error("Failed to generate valid story structure.");
  }
};

export const generateIllustration = async (prompt: string): Promise<string> => {
  const ai = getClient();

  // Using gemini-2.5-flash-image for reliable, key-based generation without OAuth complexity in this demo.
  // Ideally, for a "Pro" app, we would use gemini-3-pro-image-preview, but that requires user-selected keys.
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: prompt,
    config: {
       // Only aspect ratio is strictly supported on flash-image generally, mimeType not always needed but good practice.
       // Note: responseMimeType is NOT supported for nano banana series (flash-image) per guidelines.
    }
  });

  // Extract image
  // The output response may contain both image and text parts; you must iterate through all parts to find the image part.
  const candidates = response.candidates;
  if (candidates && candidates.length > 0 && candidates[0].content && candidates[0].content.parts) {
      for (const part of candidates[0].content.parts) {
          if (part.inlineData && part.inlineData.data) {
              return part.inlineData.data; // Base64 string
          }
      }
  }

  throw new Error("No image generated.");
};

export const regeneratePrompt = async (currentPrompt: string): Promise<string> => {
    const ai = getClient();
    // Simple text task to rewrite the prompt
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Rewrite the following image prompt to change the camera angle or composition slightly, while keeping the subject and style exactly the same. 

        Original Prompt: "${currentPrompt}"

        Return ONLY the new prompt text.`,
    });

    return response.text?.trim() || currentPrompt;
}

