import React, { useState, useEffect } from 'react';
import { StoryData, StoryParams, StoryState } from './types';
import { INITIAL_STORY_PARAMS } from './constants';
import { generateStoryStructure } from './services/gemini';
import SetupForm from './components/SetupForm';
import StoryBook from './components/StoryBook';
import { Sun, Moon } from 'lucide-react';

const App: React.FC = () => {
  const [state, setState] = useState<StoryState>({
    step: 'setup',
    params: INITIAL_STORY_PARAMS,
    data: null,
    error: null,
  });

  const [isLoading, setIsLoading] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Initialize theme based on preference
  useEffect(() => {
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setIsDarkMode(true);
    }
  }, []);

  // Update DOM when theme changes
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleParamsChange = (newParams: StoryParams) => {
    setState(prev => ({ ...prev, params: newParams }));
  };

  const handleCreateStory = async () => {
    setIsLoading(true);
    setState(prev => ({ ...prev, error: null }));

    try {
      const storyData = await generateStoryStructure(state.params);
      setState(prev => ({
        ...prev,
        step: 'reading',
        data: storyData
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({
        ...prev,
        error: "Oops! We couldn't create the story right now. Please try again."
      }));
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setState({
      step: 'setup',
      params: INITIAL_STORY_PARAMS,
      data: null,
      error: null
    });
  };

  return (
    <div className="min-h-screen bg-brand-50 dark:bg-slate-950 flex flex-col font-sans transition-colors duration-300">
      {/* Theme Toggle Button */}
      <button 
        onClick={toggleTheme}
        className="fixed top-4 right-4 z-50 p-3 rounded-full bg-white dark:bg-slate-800 text-brand-600 dark:text-brand-400 shadow-lg hover:shadow-xl transition-all border border-brand-100 dark:border-slate-700"
        aria-label="Toggle Dark Mode"
      >
        {isDarkMode ? <Sun className="w-6 h-6" /> : <Moon className="w-6 h-6" />}
      </button>

      {state.step === 'setup' && (
        <div className="flex-1 flex flex-col items-center justify-center p-4">
          <SetupForm 
            params={state.params} 
            onChange={handleParamsChange} 
            onSubmit={handleCreateStory}
            isLoading={isLoading}
          />
          {state.error && (
            <div className="mt-4 p-4 bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 rounded-xl border border-red-200 dark:border-red-800">
              {state.error}
            </div>
          )}
        </div>
      )}

      {state.step === 'reading' && state.data && (
        <StoryBook story={state.data} onReset={handleReset} />
      )}
    </div>
  );
};

export default App;

