import React from 'react';
import { BookOpen, Sparkles, Languages, Palette, Clock, Users, Check } from 'lucide-react';
import { StoryParams, Language, AgeGroup, StoryLength, ArtStyle } from '../types';
import { AGE_OPTIONS, ART_STYLES, STORY_LENGTHS } from '../constants';

interface SetupFormProps {
  params: StoryParams;
  onChange: (newParams: StoryParams) => void;
  onSubmit: () => void;
  isLoading: boolean;
}

const SetupForm: React.FC<SetupFormProps> = ({ params, onChange, onSubmit, isLoading }) => {
  const handleChange = <K extends keyof StoryParams>(key: K, value: StoryParams[K]) => {
    onChange({ ...params, [key]: value });
  };

  // Helper to map color names to Tailwind classes
  const getColorClasses = (color: string, isSelected: boolean) => {
    const base = "transition-all duration-300 relative border-2";
    const selected = isSelected ? "ring-2 ring-offset-2 transform scale-105 z-10" : "hover:scale-105 hover:z-10";

    switch (color) {
      case 'purple':
        return `${base} ${selected} ${isSelected ? 'bg-purple-100 border-purple-500 ring-purple-500' : 'bg-purple-50 border-purple-200 hover:border-purple-400'}`;
      case 'yellow':
        return `${base} ${selected} ${isSelected ? 'bg-yellow-100 border-yellow-500 ring-yellow-500' : 'bg-yellow-50 border-yellow-200 hover:border-yellow-400'}`;
      case 'blue':
        return `${base} ${selected} ${isSelected ? 'bg-blue-100 border-blue-500 ring-blue-500' : 'bg-blue-50 border-blue-200 hover:border-blue-400'}`;
      case 'orange':
        return `${base} ${selected} ${isSelected ? 'bg-orange-100 border-orange-500 ring-orange-500' : 'bg-orange-50 border-orange-200 hover:border-orange-400'}`;
      case 'pink':
        return `${base} ${selected} ${isSelected ? 'bg-pink-100 border-pink-500 ring-pink-500' : 'bg-pink-50 border-pink-200 hover:border-pink-400'}`;
      case 'amber':
        return `${base} ${selected} ${isSelected ? 'bg-amber-100 border-amber-500 ring-amber-500' : 'bg-amber-50 border-amber-200 hover:border-amber-400'}`;
      case 'violet':
        return `${base} ${selected} ${isSelected ? 'bg-violet-100 border-violet-500 ring-violet-500' : 'bg-violet-50 border-violet-200 hover:border-violet-400'}`;
      default:
        return `${base} ${selected} bg-gray-50 border-gray-200`;
    }
  };

  const getTextColor = (color: string) => {
     switch (color) {
      case 'purple': return 'text-purple-700';
      case 'yellow': return 'text-yellow-700';
      case 'blue': return 'text-blue-700';
      case 'orange': return 'text-orange-700';
      case 'pink': return 'text-pink-700';
      case 'amber': return 'text-amber-700';
      case 'violet': return 'text-violet-700';
      default: return 'text-gray-700';
    }
  }

  return (
    <div className="w-full max-w-4xl mx-auto card rounded-3xl shadow-xl overflow-hidden border-4 border-brand-100 dark:border-slate-700 transition-colors duration-300">
      <div className="bg-brand-400 dark:bg-brand-600 p-8 text-center relative overflow-hidden transition-colors duration-300">
        <div className="absolute top-0 left-0 w-full h-full bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
        <div className="relative z-10">
            <div className="inline-flex items-center justify-center p-3 card rounded-full shadow-lg mb-4">
                <BookOpen className="w-8 h-8 text-brand-600 dark:text-brand-400" />
            </div>
            <h1 className="text-3xl md:text-4xl font-heading font-bold text-white mb-2">Sawan Kids Story Studio</h1>
            <p className="text-brand-50 font-medium text-lg">Create magical stories in seconds!</p>
        </div>
      </div>

      <div className="p-8 space-y-8">

        {/* Story Idea */}
        <div className="space-y-4">
          <label className="flex items-center text-gray-700 dark:text-gray-200 font-bold font-heading text-xl">
            <Sparkles className="w-6 h-6 mr-2 text-yellow-500" />
            What is your story about?
          </label>
          <textarea
            value={params.idea}
            onChange={(e) => handleChange('idea', e.target.value)}
            placeholder="e.g., A brave little rabbit who wants to fly to the moon..."
            className="w-full p-4 border-2 border-brand-100 dark:border-slate-700 rounded-2xl focus:border-brand-400 dark:focus:border-brand-400 focus:ring-4 focus:ring-brand-100 dark:focus:ring-brand-900 transition-all outline-none resize-none h-32 text-gray-700 dark:text-gray-200 card text-lg placeholder-gray-400 dark:placeholder-gray-500"
          />
        </div>

        {/* Age Group - New Grid UI */}
        <div className="space-y-4">
          <label className="flex items-center text-gray-700 dark:text-gray-200 font-bold font-heading text-xl">
            <Users className="w-6 h-6 mr-2 text-purple-500" />
            Age Group
          </label>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {AGE_OPTIONS.map((option) => {
              const isSelected = params.ageGroup === option.id;
              const textColor = getTextColor(option.color);

              return (
                <div
                  key={option.id}
                  onClick={() => handleChange('ageGroup', option.id)}
                  className={`
                    cursor-pointer rounded-2xl p-4 flex flex-col items-center justify-center min-h-[120px] text-center
                    ${getColorClasses(option.color, isSelected)}
                  `}
                >
                  <span className={`text-2xl font-black mb-1 ${textColor}`}>{option.label}</span>
                  <span className={`text-xs font-bold uppercase tracking-wide opacity-80 ${textColor}`}>{option.title}</span>

                  {isSelected && (
                    <div className={`absolute top-2 right-2 w-6 h-6 rounded-full flex items-center justify-center ${
                      option.color === 'yellow' || option.color === 'amber' ? 'bg-black/10' : 'bg-white/30'
