.age-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 18px;
}

.age-card {
  position: relative;
  border-radius: 18px;
  padding: 18px 14px;
  text-align: center;
  cursor: pointer;
  color: #fff;
  font-weight: 600;
  transition: all 0.25s ease;
  transform: translateY(0) scale(1);
  box-shadow: 0 8px 20px rgba(0,0,0,.12);
}

.age-card:hover {
  transform: translateY(-6px) scale(1.04);
}

.age-card.active {
  outline: 3px solid #fff;
  box-shadow: 0 0 0 4px rgba(255,255,255,.35);
}

.age-range {
  font-size: 26px;
  display: block;
}

.age-title {
  font-size: 13px;
  opacity: .95;
}

.check {
  position: absolute;
  bottom: -10px;
  left: 50%;
  transform: translateX(-50%);
  background: #7c3aed;
  color: #fff;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: none;
  align-items: center;
  justify-content: center;
  font-size: 14px;
}

.age-card.active .check {
  display: flex;
}

