import React, { useState, useEffect } from 'react';
import { ArrowLeft, ArrowRight, RefreshCw, Download, Home, Wand2 } from 'lucide-react';
import { StoryData, StoryPage } from '../types';
import { generateIllustration, regeneratePrompt } from '../services/gemini';

interface StoryBookProps {
  story: StoryData;
  onReset: () => void;
}

const StoryBook: React.FC<StoryBookProps> = ({ story, onReset }) => {
  const [currentPageIndex, setCurrentPageIndex] = useState(0);
  const [pages, setPages] = useState<StoryPage[]>(story.pages);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);

  const isRTL = story.story_info.language === 'Arabic';
  const currentPage = pages[currentPageIndex];

  // Auto-generate image for the current page if missing
  useEffect(() => {
    const generateForPage = async () => {
      if (!currentPage.generatedImage && !currentPage.isGeneratingImage) {

        // Mark as generating
        setPages(prev => prev.map((p, idx) => 
          idx === currentPageIndex ? { ...p, isGeneratingImage: true } : p
        ));

        try {
          // Construct a full prompt using character info for consistency
          const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
          ).join(' ');

          const fullPrompt = `Art Style: ${story.story_info.art_style}. ${characterContext} Scene: ${currentPage.image_prompt}`;

          const base64Image = await generateIllustration(fullPrompt);

          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
          ));

        } catch (error) {
          console.error("Failed to generate image", error);
          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
          ));
        }
      }
    };

    generateForPage();
  }, [currentPageIndex, currentPage.generatedImage, currentPage.isGeneratingImage, currentPage.image_prompt, story.characters, story.story_info.art_style]);

  const handleNext = () => {
    if (currentPageIndex < pages.length - 1) {
      setCurrentPageIndex(prev => prev + 1);
    }
  };

  const handlePrev = () => {
    if (currentPageIndex > 0) {
      setCurrentPageIndex(prev => prev - 1);
    }
  };

  const handleRegenerateImage = async () => {
    if (isGeneratingImage) return;
    setIsGeneratingImage(true);

    // Clear current image and mark generating
    setPages(prev => prev.map((p, idx) => 
        idx === currentPageIndex ? { ...p, generatedImage: undefined, isGeneratingImage: true } : p
    ));

    try {
        // Step 1: Rewrite prompt
        const newPrompt = await regeneratePrompt(currentPage.image_prompt);

        // Update prompt in state (optional, but good for debugging)
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, image_prompt: newPrompt } : p
        ));

        // Step 2: Generate new image
        const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
        ).join(' ');
        const fullPrompt = `Art Style: ${story.story_info.art_style}. ${characterContext} Scene: ${newPrompt}`;

        const base64Image = await generateIllustration(fullPrompt);

        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
        ));

    } catch (e) {
        console.error("Regeneration failed", e);
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
        ));
    } finally {
        setIsGeneratingImage(false);
    }
  };

  return (
    <div className="flex flex-col h-screen max-h-screen overflow-hidden transition-colors duration-300">
      {/* Header */}
      <header className="flex items-center justify-between p-4 card shadow-sm border-b border-brand-100 dark:border-slate-800 z-20">
        <button onClick={onReset} className="flex items-center text-gray-500 dark:text-gray-400 hover:text-brand-600 dark:hover:text-brand-400 transition-colors font-bold">
          {isRTL ? <ArrowRight className="w-5 h-5 ms-2" /> : <ArrowLeft className="w-5 h-5 me-2" />}
          {isRTL ? "الرئيسية" : "Home"}
        </button>
        <h1 className={`text-xl md:text-2xl font-heading font-bold text-brand-800 dark:text-brand-400 truncate px-4 ${isRTL ? 'font-arabic' : ''}`}>
          {story.story_info.title}
        </h1>
        <div className="w-20"></div> {/* Spacer for balance */}
      </header>

      {/* Main Content Area */}
      <main className="flex-1 flex items-center justify-center p-4 md:p-8 overflow-y-auto">
        <div className="w-full max-w-6xl aspect-[4/3] md:aspect-[2/1] card rounded-2xl shadow-2xl flex flex-col md:flex-row overflow-hidden border border-gray-100 dark:border-slate-800 relative transition-colors duration-300">

          {/* Text Side */}
          <div className="flex-1 p-8 md:p-12 flex flex-col justify-center items-start card overflow-y-auto z-10 transition-colors duration-300">
            <div className="w-full h-full flex flex-col justify-center">
                <span className="text-brand-300 dark:text-brand-900 font-heading font-bold text-6xl opacity-20 mb-4 select-none">
                    {currentPage.page}
                </span>
                <p className={`text-2xl md:text-3xl leading-relaxed text-gray-800 dark:text-gray-100 font-medium ${isRTL ? 'font-arabic' : 'font-heading'}`}>
                {currentPage.text}
                </p>
            </div>
          </div>

          {/* Image Side */}
          <div className="flex-1 relative bg-brand-50 dark:bg-slate-950 flex items-center justify-center">
            {currentPage.generatedImage ? (
                <>
                    <img 
                        src={`data:image/jpeg;base64,${currentPage.generatedImage}`} 
                        alt={currentPage.image_prompt}
                        className="w-full h-full object-cover"
                    />
                    <div className="absolute top-4 right-4 rtl:left-4 rtl:right-auto">
                        <button 
                            onClick={handleRegenerateImage}
                            disabled={currentPage.isGeneratingImage}
                            className="bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 backdrop-blur-sm p-2 rounded-full shadow-lg text-brand-600 dark:text-brand-400 hover:text-brand-800 transition-all"
                            title="Regenerate Image"
                        >
                            <RefreshCw className={`w-5 h-5 ${currentPage.isGeneratingImage ? 'animate-spin' : ''}`} />
                        </button>
                    </div>
                </>
            ) : (
                <div className="flex flex-col items-center p-8 text-center animate-pulse">
                    <Wand2 className="w-16 h-16 text-brand-300 dark:text-slate-700 mb-4 animate-bounce" />
                    <p className="text-brand-400 dark:text-slate-600 font-heading text-lg">
                        {isRTL ? "جارٍ رسم المشهد..." : "Painting this page..."}
                    </p>
                    <p className="text-brand-300 dark:text-slate-700 text-sm mt-2 max-w-xs">{currentPage.image_prompt.substring(0, 100)}...</p>
                </div>
            )}
          </div>

        </div>
      </main>

      {/* Footer Navigation */}
      <footer className="p-6 card border-t border-brand-100 dark:border-slate-800 flex items-center justify-between z-20 transition-colors duration-300">
        <button 
            onClick={handlePrev} 
            disabled={currentPageIndex === 0}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === 0 
                ? 'text-gray-300 dark:text-slate-700 cursor-not-allowed' 
                : 'bg-brand-100 dark:bg-slate-800 text-brand-700 dark:text-brand-400 hover:bg-brand-200 dark:hover:bg-slate-700'
            }`}
        >
            {isRTL ? <ArrowRight className="w-5 h-5 ms-2" /> : <ArrowLeft className="w-5 h-5 me-2" />}
            {isRTL ? "السابق" : "Previous"}
        </button>

        <div className="flex gap-2">
            {pages.map((_, idx) => (
                <div 
                    key={idx}
                    className={`w-3 h-3 rounded-full transition-all ${
                        idx === currentPageIndex ? 'bg-brand-500 dark:bg-brand-400 scale-125' : 'bg-gray-200 dark:bg-slate-700'
                    }`}
                />
            ))}
        </div>

        <button 
            onClick={handleNext} 
            disabled={currentPageIndex === pages.length - 1}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === pages.length - 1 
                ? 'text-gray-300 dark:text-slate-700 cursor-not-allowed' 
                : 'bg-brand-500 dark:bg-brand-600 text-white hover:bg-brand-600 dark:hover:bg-brand-500 shadow-lg'
            }`}
        >
            {isRTL ? "التالي" : "Next"}
            {isRTL ? <ArrowLeft className="w-5 h-5 me-2" /> : <ArrowRight className="w-5 h-5 ms-2" />}
        </button>
      </footer>
    </div>
  );
};

export default StoryBook;

import React, { useState, useEffect } from 'react';
import { StoryData, StoryParams, StoryState } from './types';
import { INITIAL_STORY_PARAMS } from './constants';
import { generateStoryStructure } from './services/gemini';
import SetupForm from './components/SetupForm';
import StoryBook from './components/StoryBook';
import { Sun, Moon } from 'lucide-react';

const App: React.FC = () => {
  const [state, setState] = useState<StoryState>({
    step: 'setup',
    params: INITIAL_STORY_PARAMS,
    data: null,
    error: null,
  });

  const [isLoading, setIsLoading] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Initialize theme and language on load
  useEffect(() => {
    // 1. Theme Initialization
    const savedTheme = localStorage.getItem("theme");
    if (savedTheme) {
      document.documentElement.setAttribute("data-theme", savedTheme);
      setIsDarkMode(savedTheme === 'dark');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      document.documentElement.setAttribute("data-theme", 'dark');
      setIsDarkMode(true);
    }

    // 2. Language Initialization
    const savedLang = localStorage.getItem("lang");
    if (savedLang) {
        // setLang logic: Apply immediately to DOM
        document.documentElement.lang = savedLang;
        document.documentElement.dir = savedLang === "ar" ? "rtl" : "ltr";

        // Sync React State to match saved language
        const languageLabel = savedLang === 'ar' ? 'Arabic' : 'English';
        setState(prev => ({
            ...prev,
            params: { ...prev.params, language: languageLabel }
        }));
    }
  }, []);

  // Sync Language with DOM and LocalStorage on state change
  useEffect(() => {
    const lang = state.params.language;
    const langCode = lang === 'Arabic' ? 'ar' : 'en';
    const dir = lang === 'Arabic' ? 'rtl' : 'ltr';

    document.documentElement.lang = langCode;
    document.documentElement.dir = dir;
    localStorage.setItem("lang", langCode);
  }, [state.params.language]);

  const toggleTheme = () => {
    const newTheme = isDarkMode ? 'light' : 'dark';
    document.documentElement.setAttribute("data-theme", newTheme);
    localStorage.setItem("theme", newTheme);
    setIsDarkMode(!isDarkMode);
  };

  const toggleLanguage = () => {
    const currentLang = state.params.language;
    const newLang = currentLang === 'English' ? 'Arabic' : 'English';
    setState(prev => ({
        ...prev,
        params: { ...prev.params, language: newLang }
    }));
  };

  const handleParamsChange = (newParams: StoryParams) => {
    setState(prev => ({ ...prev, params: newParams }));
  };

  const handleCreateStory = async () => {
    setIsLoading(true);
    setState(prev => ({ ...prev, error: null }));

    try {
      const storyData = await generateStoryStructure(state.params);
      setState(prev => ({
        ...prev,
        step: 'reading',
        data: storyData
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({
        ...prev,
        error: "Oops! We couldn't create the story right now. Please try again."
      }));
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = () => {
    setState({
      step: 'setup',
      params: INITIAL_STORY_PARAMS,
      data: null,
      error: null
    });
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      {/* Global Header Controls */}
      <div className="fixed top-4 right-4 z-50 flex gap-3">
        {/* Language Toggle */}
        <button 
          onClick={toggleLanguage}
          className="p-3 rounded-full card text-2xl shadow-lg hover:shadow-xl transition-all border border-brand-100 dark:border-slate-700 flex items-center justify-center w-12 h-12"
          aria-label="Toggle Language"
          title={state.params.language === 'English' ? "Switch to Arabic" : "Switch to English"}
        >
          {state.params.language === 'English' ? '🇪🇬' : '🇺🇸'}
        </button>

        {/* Theme Toggle */}
        <button 
          onClick={toggleTheme}
          className="p-3 rounded-full card text-brand-600 dark:text-brand-400 shadow-lg hover:shadow-xl transition-all border border-brand-100 dark:border-slate-700 flex items-center justify-center w-12 h-12"
          aria-label="Toggle Dark Mode"
        >
          {isDarkMode ? <Sun className="w-6 h-6" /> : <Moon className="w-6 h-6" />}
        </button>
      </div>

      {state.step === 'setup' && (
        <div className="flex-1 flex flex-col items-center justify-center p-4">
          <SetupForm 
            params={state.params} 
            onChange={handleParamsChange} 
            onSubmit={handleCreateStory}
            isLoading={isLoading}
          />
          {state.error && (
            <div className="mt-4 p-4 bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 rounded-xl border border-red-200 dark:border-red-800">
              {state.error}
            </div>
          )}
        </div>
      )}

      {state.step === 'reading' && state.data && (
        <StoryBook story={state.data} onReset={handleReset} />
      )}
    </div>
  );
};

export default App;

