import React from 'react';
import { BookOpen, Sparkles, Languages, Palette, Clock, Users, Check } from 'lucide-react';
import { StoryParams, Language, AgeGroup, StoryLength, ArtStyle } from '../types';
import { AGE_OPTIONS, ART_STYLES, STORY_LENGTHS } from '../constants';

interface SetupFormProps {
  params: StoryParams;
  onChange: (newParams: StoryParams) => void;
  onSubmit: () => void;
  isLoading: boolean;
}

const SetupForm: React.FC<SetupFormProps> = ({ params, onChange, onSubmit, isLoading }) => {
  const handleChange = <K extends keyof StoryParams>(key: K, value: StoryParams[K]) => {
    onChange({ ...params, [key]: value });
  };

  return (
    <div className="w-full max-w-4xl mx-auto card rounded-3xl shadow-xl overflow-hidden border-4 border-brand-100 dark:border-slate-700 transition-colors duration-300">
      <div className="bg-brand-400 dark:bg-brand-600 p-8 text-center relative overflow-hidden transition-colors duration-300">
        <div className="absolute top-0 left-0 w-full h-full bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
        <div className="relative z-10">
            <div className="inline-flex items-center justify-center p-3 card rounded-full shadow-lg mb-4">
                <BookOpen className="w-8 h-8 text-brand-600 dark:text-brand-400" />
            </div>
            <h1 className="text-3xl md:text-4xl font-heading font-bold text-white mb-2">Sawan Kids Story Studio</h1>
            <p className="text-brand-50 font-medium text-lg">Create magical stories in seconds!</p>
        </div>
      </div>

      <div className="p-8 space-y-8">

        {/* Story Idea */}
        <div className="space-y-4">
          <label className="flex items-center text-gray-700 dark:text-gray-200 font-bold font-heading text-xl">
            <Sparkles className="w-6 h-6 me-2 text-yellow-500" />
            What is your story about?
          </label>
          <textarea
            value={params.idea}
            onChange={(e) => handleChange('idea', e.target.value)}
            placeholder={params.language === 'Arabic' ? "عن ماذا تدور القصة؟ (مثلاً: أرنب شجاع يريد الطيران...)" : "e.g., A brave little rabbit who wants to fly to the moon..."}
            dir="auto"
            className="w-full p-4 border-2 border-brand-100 dark:border-slate-700 rounded-2xl focus:border-brand-400 dark:focus:border-brand-400 focus:ring-4 focus:ring-brand-100 dark:focus:ring-brand-900 transition-all outline-none resize-none h-32 text-gray-700 dark:text-gray-200 card text-lg placeholder-gray-400 dark:placeholder-gray-500"
          />
        </div>

        {/* Age Group - New Custom CSS Grid UI */}
        <div className="space-y-4">
          <label className="flex items-center text-gray-700 dark:text-gray-200 font-bold font-heading text-xl">
            <Users className="w-6 h-6 me-2 text-purple-500" />
            Age Group
          </label>

          <div className="age-grid">
            {AGE_OPTIONS.map((option) => {
              const isSelected = params.ageGroup === option.id;

              return (
                <div
                  key={option.id}
                  onClick={() => handleChange('ageGroup', option.id)}
                  className={`age-card age-${option.color} ${isSelected ? 'active' : ''}`}
                >
                  <span className="age-range">{option.label}</span>
                  <span className="age-title">{option.title}</span>
                  <div className="check">✓</div>
                </div>
