          {/* Language */}
          <div className="space-y-4">
            <label className="flex items-center text-gray-700 dark:text-gray-200 font-bold font-heading text-lg">
              <Languages className="w-5 h-5 me-2 text-green-500" />
              Language
            </label>
            <div className="flex gap-3">
