/* =====================
   STORY SETTINGS LOGIC
===================== */
let storySettings = {
  pages: 6,
  ratio: "9:16"
};

const slider = document.getElementById("pagesSlider");
const pagesValue = document.getElementById("pagesValue");
const preview = document.getElementById("previewFrame");

/* Slider */
slider.oninput = (e) => {
  storySettings.pages = e.target.value;
  pagesValue.innerText = e.target.value;
  clearPresets();
};

/* Presets */
document.querySelectorAll(".preset").forEach(btn => {
  btn.onclick = () => {
    document.querySelectorAll(".preset").forEach(b => b.classList.remove("active"));
    btn.classList.add("active");
    slider.value = btn.dataset.pages;
    pagesValue.innerText = btn.dataset.pages;
    storySettings.pages = btn.dataset.pages;
  };
});

function clearPresets(){
  document.querySelectorAll(".preset").forEach(b => b.classList.remove("active"));
}

/* Ratio */
document.querySelectorAll("#ratioCards .card").forEach(card => {
  card.onclick = () => {
    document.querySelectorAll("#ratioCards .card").forEach(c => c.classList.remove("active"));
    card.classList.add("active");
    storySettings.ratio = card.dataset.value;

    preview.className = "preview " + (storySettings.ratio === "9:16" ? "vertical" : "horizontal");
  };
});

