  const isPreset = (val: number) => [6, 12, 20].includes(val);
  const [activePreset, setActivePreset] = useState<number | null>(
    isPreset(params.pageCount) ? params.pageCount : null
  );

  const handlePresetClick = (count: number) => {
    handleChange('pageCount', count);
    setActivePreset(count);
  };

  const handleSliderChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    handleChange('pageCount', parseInt(e.target.value));
    setActivePreset(null);
  };

  const t = {
    English: {
      storyAbout: "What is your story about?",
      storyPlaceholder: "e.g., A brave little rabbit who wants to fly to the moon...",
      ageGroup: "Age Group",
      language: "Language",
      storySettings: "Story Settings",
      pagesLabel: "Number of Pages",
      ratioLabel: "Image Orientation",
      vertical: "Vertical",
      horizontal: "Horizontal",
      artStyle: "Art Style",
      createBtn: "Create My Story!",
      creatingBtn: "Creating Magic...",
      presetQuick: "Quick",
      presetNormal: "Normal",
      presetLong: "Long",
      previewText: "Story Preview"
