                  params.language === 'Arabic'
                    ? 'bg-brand-500 border-brand-500 text-white shadow-lg transform scale-105'
                    : 'card border-gray-200 dark:border-slate-700 text-gray-500 dark:text-gray-400 hover:border-brand-200 dark:hover:border-slate-600'
                }`}
              >
                <span className="text-2xl">🇪🇬</span> <span className="font-arabic">العربية</span>
              </button>
            </div>
          </div>

          {/* Story Settings */}
          <div className="space-y-4">
            <label className="flex items-center text-gray-700 dark:text-gray-200 font-bold font-heading text-lg">
              <Settings className="w-5 h-5 me-2 text-orange-500" />
              {txt.storySettings}
            </label>

            <div className="card p-6 rounded-2xl border-2 border-gray-100 dark:border-slate-800">

                {/* Presets */}
                <div className="flex gap-[10px] mb-[14px]">
