                        <button
                            key={preset.count}
                            onClick={() => handlePresetClick(preset.count)}
                            className={`flex-1 p-[10px] rounded-xl border-none cursor-pointer transition-colors font-bold ${
                                activePreset === preset.count
                                ? 'bg-green-500 text-black' 
                                : 'bg-gray-800 text-white'
                            }`}
                        >
                            {preset.label}
                        </button>
                    ))}
                </div>

                {/* Pages Slider */}
                <div className="mb-5">
                     <div className="flex justify-between mb-2">
                        <label className="text-sm font-bold text-gray-500 dark:text-gray-400">{txt.pagesLabel}</label>
                        <span className="font-heading font-bold text-brand-600 dark:text-brand-400 text-lg" id="pagesValue">{params.pageCount}</span>
                     </div>
                     <input
                        type="range"
                        min="3"
