import React, { useState, useEffect } from "react";

interface StoryBookProps {
  story: any; // Define the type for the story object
  onBack: () => void;
  onShare: () => void;
}

const StoryBook: React.FC<StoryBookProps> = ({ story, onBack, onShare }) => {
