import React, { useState, useEffect } from 'react';
import { ArrowLeft, ArrowRight, RefreshCw, Download, Home, Wand2, Save } from 'lucide-react';
import { StoryData, StoryPage, AspectRatio } from '../types';
import { generateIllustration, regeneratePrompt } from '../services/gemini';

interface StoryBookProps {
  story: StoryData;
  onReset: () => void;
}

const StoryBook: React.FC<StoryBookProps> = ({ story, onReset }) => {
  const [currentPageIndex, setCurrentPageIndex] = useState(0);
  const [pages, setPages] = useState<StoryPage[]>(story.pages);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);

  const isRTL = story.story_info.language === 'Arabic';
  const currentPage = pages[currentPageIndex];

  // Use aspect ratio from story info, default to 16:9 if missing
  const aspectRatio: AspectRatio = (story.story_info.aspect_ratio as AspectRatio) || '16:9';
  const isVertical = aspectRatio === '9:16';

  // Auto-generate image for the current page if missing
  useEffect(() => {
    const generateForPage = async () => {
      if (!currentPage.generatedImage && !currentPage.isGeneratingImage) {

        // Mark as generating
        setPages(prev => prev.map((p, idx) => 
          idx === currentPageIndex ? { ...p, isGeneratingImage: true } : p
        ));

        try {
          // Construct a full prompt using character info for consistency
          const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
          ).join(' ');

          const fullPrompt = `Art Style: ${story.story_info.art_style}. ${characterContext} Scene: ${currentPage.image_prompt}`;

          const base64Image = await generateIllustration(fullPrompt, aspectRatio);

          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
          ));

        } catch (error) {
          console.error("Failed to generate image", error);
          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
          ));
        }
      }
    };

    generateForPage();
  }, [currentPageIndex, currentPage.generatedImage, currentPage.isGeneratingImage, currentPage.image_prompt, story.characters, story.story_info.art_style, aspectRatio]);

  const handleNext = () => {
    if (currentPageIndex < pages.length - 1) {
      setCurrentPageIndex(prev => prev + 1);
    }
  };

  const handlePrev = () => {
    if (currentPageIndex > 0) {
      setCurrentPageIndex(prev => prev - 1);
    }
  };

  const handleRegenerateImage = async () => {
    if (isGeneratingImage) return;
    setIsGeneratingImage(true);

    // Clear current image and mark generating
    setPages(prev => prev.map((p, idx) => 
        idx === currentPageIndex ? { ...p, generatedImage: undefined, isGeneratingImage: true } : p
    ));

    try {
        // Step 1: Rewrite prompt
        const newPrompt = await regeneratePrompt(currentPage.image_prompt);

        // Update prompt in state
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, image_prompt: newPrompt } : p
        ));

        // Step 2: Generate new image
        const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
        ).join(' ');
        const fullPrompt = `Art Style: ${story.story_info.art_style}. ${characterContext} Scene: ${newPrompt}`;

        const base64Image = await generateIllustration(fullPrompt, aspectRatio);

        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
        ));

    } catch (e) {
        console.error("Regeneration failed", e);
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
        ));
    } finally {
        setIsGeneratingImage(false);
    }
  };

  const handleSave = () => {
    const cleanPages = pages.map(({ isGeneratingImage, ...rest }) => rest);

    const storyData = {
      ...story,
      pages: cleanPages,
      savedAt: new Date().toISOString()
    };

    try {
      localStorage.setItem("sawan_story", JSON.stringify(storyData));
      alert(isRTL ? "✅ تم حفظ القصة بنجاح!" : "✅ Story saved successfully!");
    } catch (e) {
      console.warn("LocalStorage quota exceeded or error, falling back to download", e);

      const jsonString = JSON.stringify(storyData, null, 2);
      const blob = new Blob([jsonString], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `${story.story_info.title.replace(/\s+/g, "_") || "story"}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      alert(isRTL ? "القصة كبيرة جداً للحفظ في المتصفح. تم تنزيلها كملف بدلاً من ذلك." : "Story is too large for browser storage. Downloaded as file instead.");
    }
  };

  return (
    <div className="flex flex-col h-screen max-h-screen overflow-hidden transition-colors duration-300">
      {/* Header */}
      <header className="flex items-center justify-between p-4 card shadow-sm border-b border-brand-100 dark:border-slate-800 z-20">
        <button onClick={onReset} className="flex items-center text-gray-500 dark:text-gray-400 hover:text-brand-600 dark:hover:text-brand-400 transition-colors font-bold">
          {isRTL ? <ArrowRight className="w-5 h-5 ms-2" /> : <ArrowLeft className="w-5 h-5 me-2" />}
          {isRTL ? "الرئيسية" : "Home"}
        </button>
        <h1 className={`text-xl md:text-2xl font-heading font-bold text-brand-800 dark:text-brand-400 truncate px-4 ${isRTL ? 'font-arabic' : ''}`} id="storyTitle">
          {story.story_info.title}
        </h1>
        <button 
          id="saveStory"
          onClick={handleSave}
          className="flex items-center text-brand-600 dark:text-brand-400 hover:text-brand-800 dark:hover:text-brand-300 transition-colors font-bold gap-2"
        >
          <Save className="w-5 h-5" />
          <span className="hidden md:inline">{isRTL ? "حفظ القصة" : "Save Story"}</span>
        </button>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 flex items-center justify-center p-4 md:p-8 overflow-y-auto">

        <div className={`
          w-full card rounded-2xl shadow-2xl flex flex-col md:flex-row overflow-hidden border border-gray-100 dark:border-slate-800 relative transition-colors duration-300
          ${isVertical ? 'max-w-4xl h-[85vh] md:h-[80vh]' : 'max-w-6xl aspect-[4/3] md:aspect-[2/1]'}
        `}>

          {/* Text Side */}
          <div className="flex-1 p-8 md:p-12 flex flex-col justify-center items-start card overflow-y-auto z-10 transition-colors duration-300">
            <div className="w-full h-full flex flex-col justify-center">
                <span className="text-brand-300 dark:text-brand-900 font-heading font-bold text-6xl opacity-20 mb-4 select-none">
                    {currentPage.page}
                </span>
                <p className={`text-2xl md:text-3xl leading-relaxed text-gray-800 dark:text-gray-100 font-medium ${isRTL ? 'font-arabic' : 'font-heading'}`}>
                {currentPage.text}
                </p>
            </div>
          </div>

          {/* Image Side */}
          <div className={`
            relative bg-brand-50 dark:bg-slate-950 flex items-center justify-center
            ${isVertical ? 'flex-1 h-1/2 md:h-full md:w-1/2 order-first md:order-last' : 'flex-1'}
          `}>
            {currentPage.generatedImage ? (
                <>
                    <img 
                        src={`data:image/jpeg;base64,${currentPage.generatedImage}`} 
                        alt={currentPage.image_prompt}
                        className="w-full h-full object-cover"
                    />
                    <div className="absolute top-4 right-4 rtl:left-4 rtl:right-auto flex gap-2">
                        <a 
                            href={`data:image/jpeg;base64,${currentPage.generatedImage}`} 
                            download={`story_page_${currentPage.page}.jpg`}
                            className="bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 backdrop-blur-sm p-2 rounded-full shadow-lg text-brand-600 dark:text-brand-400 hover:text-brand-800 transition-all flex items-center justify-center"
                            title="Download Image"
                        >
                            <Download className="w-5 h-5" />
                        </a>
                        <button 
                            onClick={handleRegenerateImage}
                            disabled={currentPage.isGeneratingImage}
                            className="bg-white/80 dark:bg-slate-800/80 hover:bg-white dark:hover:bg-slate-800 backdrop-blur-sm p-2 rounded-full shadow-lg text-brand-600 dark:text-brand-400 hover:text-brand-800 transition-all"
                            title="Regenerate Image"
                        >
                            <RefreshCw className={`w-5 h-5 ${currentPage.isGeneratingImage ? 'animate-spin' : ''}`} />
                        </button>
                    </div>
                </>
            ) : (
                <div className="flex flex-col items-center p-8 text-center animate-pulse">
                    <Wand2 className="w-16 h-16 text-brand-300 dark:text-slate-700 mb-4 animate-bounce" />
                    <p className="text-brand-400 dark:text-slate-600 font-heading text-lg">
                        {isRTL ? "جارٍ رسم المشهد..." : "Painting this page..."}
                    </p>
                    <p className="text-brand-300 dark:text-slate-700 text-sm mt-2 max-w-xs">{currentPage.image_prompt.substring(0, 100)}...</p>
                </div>
            )}
          </div>

        </div>
      </main>

      {/* Footer Navigation */}
      <footer className="p-6 card border-t border-brand-100 dark:border-slate-800 flex items-center justify-between z-20 transition-colors duration-300">
        <button 
            onClick={handlePrev} 
            disabled={currentPageIndex === 0}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === 0 
                ? 'text-gray-300 dark:text-slate-700 cursor-not-allowed' 
                : 'bg-brand-100 dark:bg-slate-800 text-brand-700 dark:text-brand-400 hover:bg-brand-200 dark:hover:bg-slate-700'
            }`}
        >
            {isRTL ? <ArrowRight className="w-5 h-5 ms-2" /> : <ArrowLeft className="w-5 h-5 me-2" />}
            {isRTL ? "السابق" : "Previous"}
        </button>

        <div className="hidden md:flex gap-2">
            {pages.map((_, idx) => (
                <div 
                    key={idx}
                    className={`w-3 h-3 rounded-full transition-all ${
                        idx === currentPageIndex ? 'bg-brand-500 dark:bg-brand-400 scale-125' : 'bg-gray-200 dark:bg-slate-700'
                    }`}
                />
            ))}
        </div>
        <div className="md:hidden text-gray-500 font-bold">
            {currentPageIndex + 1} / {pages.length}
        </div>

        <button 
            onClick={handleNext} 
            disabled={currentPageIndex === pages.length - 1}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === pages.length - 1 
                ? 'text-gray-300 dark:text-slate-700 cursor-not-allowed' 
                : 'bg-brand-500 dark:bg-brand-600 text-white hover:bg-brand-600 dark:hover:bg-brand-500 shadow-lg'
            }`}
        >
            {isRTL ? "التالي" : "Next"}
            {isRTL ? <ArrowLeft className="w-5 h-5 me-2" /> : <ArrowRight className="w-5 h-5 ms-2" />}
        </button>
      </footer>
    </div>
  );
};

