let totalPages = 3000;
let batchSize = 20;
let generatedPages = 0;
let paused = false;
let story = [];
let chapterCount = 1;

const progressBar = document.getElementById("progressBar");
const progressText = document.getElementById("progressText");
const output = document.getElementById("storyOutput");

async function generateBatch() {
  if (paused || generatedPages >= totalPages) return;

  const pagesThisBatch = Math.min(batchSize, totalPages - generatedPages);

  // 🔹 Auto Chapter Logic
  if (generatedPages % 100 === 0) {
    story.push(`\n📘 Chapter ${chapterCount}\n`);
    chapterCount++;
  }

  // 🔹 Simulated AI generation (replace with Gemini)
  for (let i = 0; i < pagesThisBatch; i++) {
    story.push(`Page ${generatedPages + 1}: Story content here...`);
    generatedPages++;
  }

  // 🔹 Update UI
  const progress = Math.round((generatedPages / totalPages) * 100);
  progressBar.style.width = progress + "%";
  progressText.textContent = progress + "%";

  output.textContent = story.join("\n");

  // 🔹 Continue generation
  setTimeout(generateBatch, 500);
}

