import React, { useState, useEffect, useRef } from 'react';
import { StoryParams, StoryState } from './types';
import { INITIAL_STORY_PARAMS } from './constants';
import { StoryGenerator } from './services/gemini';
import SetupForm from './components/SetupForm';
import StoryBook from './components/StoryBook';

// Apply Language Helper - Defined outside to run immediately
const applyLanguage = (langCode: string) => {
  const html = document.documentElement;

  // Persist choice
  localStorage.setItem("uiLang", langCode);

  if (langCode === "ar") {
    html.setAttribute("lang", "ar");
    html.setAttribute("dir", "rtl");
    html.classList.add("rtl");
  } else {
    html.setAttribute("lang", "en");
    html.setAttribute("dir", "ltr");
    html.classList.remove("rtl");
  }
};

// Run immediately to set initial document state before React renders
const savedUiLang = localStorage.getItem("uiLang") || "en";
applyLanguage(savedUiLang);

const App: React.FC = () => {
  const [state, setState] = useState<StoryState>({
    step: 'setup',
    params: {
      ...INITIAL_STORY_PARAMS,
      // Initialize state language based on persisted value to match DOM
      language: (localStorage.getItem("uiLang") === 'ar' ? 'Arabic' : 'English')
    },
    data: null,
    error: null,
  });

  const [isLoading, setIsLoading] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Generation Control State
  const [progress, setProgress] = useState(0);
  const [progressMessage, setProgressMessage] = useState("Starting...");
  const [isPaused, setIsPaused] = useState(false);

  // Use a ref for the generator so it persists across renders
  const generatorRef = useRef<StoryGenerator>(new StoryGenerator());

  // Initialize theme on mount
  useEffect(() => {
    const savedTheme = localStorage.getItem("theme");
    if (savedTheme) {
      document.documentElement.setAttribute("data-theme", savedTheme);
      setIsDarkMode(savedTheme === 'dark');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      document.documentElement.setAttribute("data-theme", 'dark');
      setIsDarkMode(true);
    }
  }, []);

  // Sync Language with DOM when state changes
  useEffect(() => {
    const lang = state.params.language;
    const langCode = lang === 'Arabic' ? 'ar' : 'en';
    applyLanguage(langCode);
  }, [state.params.language]);

  const toggleTheme = () => {
    const newTheme = isDarkMode ? 'light' : 'dark';
    document.documentElement.setAttribute("data-theme", newTheme);
    localStorage.setItem("theme", newTheme);
    setIsDarkMode(!isDarkMode);
  };

  const toggleLanguage = () => {
    const currentLang = state.params.language;
    const newLang = currentLang === 'English' ? 'Arabic' : 'English';

    setState(prev => ({
        ...prev,
        params: { ...prev.params, language: newLang }
    }));
  };

  const handleParamsChange = (newParams: StoryParams) => {
    setState(prev => ({ ...prev, params: newParams }));
  };

  const handleCreateStory = async () => {
    setIsLoading(true);
    setState(prev => ({ ...prev, error: null }));
    setProgress(0);
    setProgressMessage(state.params.language === 'Arabic' ? "جاري التحضير..." : "Preparing...");
    setIsPaused(false);

    // Ensure generator is reset/ready
    generatorRef.current.resume();

    try {
      const storyData = await generatorRef.current.generate(
        state.params, 
        (prog, msg) => {
          setProgress(prog);
          setProgressMessage(msg);
        }
      );

      setState(prev => ({
        ...prev,
        step: 'reading',
        data: storyData
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({
        ...prev,
        error: "Oops! We couldn't create the story right now. Please try again."
      }));
    } finally {
      setIsLoading(false);
    }
  };

  const handlePause = () => {
    setIsPaused(true);
    generatorRef.current.pause();
  };

  const handleResume = () => {
    setIsPaused(false);
    generatorRef.current.resume();
  };

  const handleLoadStory = () => {
    const savedData = localStorage.getItem("sawan_story");
    const isArabic = state.params.language === 'Arabic';

    const loadFromFile = () => {
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = 'application/json';
      input.onchange = (e) => {
        const file = (e.target as HTMLInputElement).files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
          try {
            const json = JSON.parse(event.target?.result as string);
            // Basic validation to ensure it looks like a story
            if (json.story_info && json.pages) {
                setState(prev => ({
                    ...prev,
                    step: 'reading',
                    data: json
                }));
            } else {
                throw new Error("Invalid story format");
            }
          } catch (err) {
            alert(isArabic ? "ملف غير صالح." : "Invalid story file.");
          }
        };
        reader.readAsText(file);
      };
      input.click();
    };

    if (savedData) {
      const message = isArabic 
        ? "وجدنا قصة محفوظة في المتصفح. هل تريد استكمالها؟\n\nاضغط 'موافق' للتحميل.\nاضغط 'إلغاء' لرفع ملف قصة من جهازك."
        : "Found a saved story in browser storage. Do you want to load it?\n\nClick 'OK' to load saved story.\nClick 'Cancel' to upload a file from your device.";

      if (window.confirm(message)) {
        try {
          const story = JSON.parse(savedData);
          setState(prev => ({
            ...prev,
            step: 'reading',
            data: story
          }));
        } catch (e) {
           console.error("Failed to load local story", e);
           loadFromFile();
        }
      } else {
        loadFromFile();
      }
    } else {
      loadFromFile();
    }
  };

  const handleReset = () => {
    setState({
      step: 'setup',
      params: {
        ...INITIAL_STORY_PARAMS,
        // Preserve current language selection on reset
        language: state.params.language
      },
      data: null,
      error: null
    });
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      {/* Global Header Controls */}
      <div className="top-actions">
        <button 
          id="themeToggle" 
          type="button"
          onClick={toggleTheme} 
          title={isDarkMode ? "Light Mode" : "Dark Mode"}
        >
          {isDarkMode ? '☀️' : '🌙'}
        </button>

        <button 
          id="langToggle" 
          type="button"
          onClick={toggleLanguage}
          title={state.params.language === 'English' ? "العربية" : "English"}
        >
          {/* Flag represents the TARGET language to switch to, or current status indicator */}
          <img 
            src={state.params.language === 'English' ? "https://flagcdn.com/w40/eg.png" : "https://flagcdn.com/w40/us.png"} 
            alt={state.params.language === 'English' ? "Arabic" : "English"} 
          />
        </button>
      </div>

      {state.step === 'setup' && (
        <div className="flex-1 flex flex-col items-center justify-center p-4">
          <SetupForm 
            params={state.params} 
            onChange={handleParamsChange} 
            onSubmit={handleCreateStory}
            onLoadStory={handleLoadStory}
            isLoading={isLoading}
            progress={progress}
            progressMessage={progressMessage}
            isPaused={isPaused}
            onPause={handlePause}
            onResume={handleResume}
          />
          {state.error && (
            <div className="mt-4 p-4 bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 rounded-xl border border-red-200 dark:border-red-800">
              {state.error}
            </div>
          )}
        </div>
      )}

      {state.step === 'reading' && state.data && (
        <StoryBook story={state.data} onReset={handleReset} />
      )}
    </div>
  );
};

export default App;

export type Language = 'English' | 'Arabic';
export type AgeGroup = '3-4' | '4-6' | '7-9' | '9-12';
export type AspectRatio = '9:16' | '16:9';
export type ArtStyle = 'Cute Cartoon' | 'Storybook Watercolor' | 'Pixar-like 3D' | 'Soft Pastel Illustration' | 'Photorealistic Human Style';

export interface StoryParams {
  idea: string;
  language: Language;
  ageGroup: AgeGroup;
  pageCount: number;
  aspectRatio: AspectRatio;
  artStyle: ArtStyle;
}

export interface Character {
  name: string;
  description: string;
  personality: string;
  age: string | number;
  gender: string;
}

export interface StoryPage {
  page: number;
  text: string;
  image_prompt: string;
  generatedImage?: string; // base64 data
  isGeneratingImage?: boolean;
}

export interface StoryData {
  story_info: {
    title: string;
    language: string;
    age_group: string;
    art_style: string;
    // We inject aspect_ratio manually in the service layer because strict JSON output from AI doesn't include it
    aspect_ratio: AspectRatio; 
  };
  characters: Character[];
  pages: StoryPage[];
}

export interface StoryState {
  step: 'setup' | 'generating_story' | 'reading';
  params: StoryParams;
  data: StoryData | null;
  error: string | null;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { StoryData, StoryParams, AspectRatio, StoryPage } from "../types";
import { SYSTEM_INSTRUCTION } from "../constants";

// Helper to get client with key
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found. Please check your environment variables.");
  }
  return new GoogleGenAI({ apiKey });
};

const BATCH_SIZE = 20;

export class StoryGenerator {
  private isPaused = false;
  private resumeResolver: (() => void) | null = null;
  private ai = getClient();

  public pause() {
    this.isPaused = true;
  }

  public resume() {
    this.isPaused = false;
    if (this.resumeResolver) {
      this.resumeResolver();
      this.resumeResolver = null;
    }
  }

  private async checkPause() {
    if (this.isPaused) {
      await new Promise<void>((resolve) => {
        this.resumeResolver = resolve;
      });
    }
  }

  public async generate(
    params: StoryParams, 
    onProgress: (progress: number, message: string) => void
  ): Promise<StoryData> {
    const totalPages = params.pageCount;

    // 1. Initial Batch
    onProgress(10, "Designing characters and plot...");
    await this.checkPause();

    const initialPageCount = Math.min(totalPages, BATCH_SIZE);

    // Add specific description if Photorealistic Human Style is selected
    const artStyleDescription = params.artStyle === 'Photorealistic Human Style'
      ? 'Photorealistic Human Style (Ultra realistic lighting, skin texture, natural facial expressions)'
      : params.artStyle;

    // Strict prompt based on the user's setup requirements
    const prompt = `
      Create a children's story based on the following inputs:
      1. Story Idea: ${params.idea}
      2. Language: ${params.language}
      3. Age Group: ${params.ageGroup}
      4. Length: ${initialPageCount} pages ${totalPages > BATCH_SIZE ? `(Part 1 of ${totalPages})` : ''}
      5. Art Style: ${artStyleDescription}

      Follow all quality rules and strict JSON output format defined in the system instructions.
      Ensure you generate exactly ${initialPageCount} pages in this batch.
    `;

    const pageSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        page: { type: Type.INTEGER },
        text: { type: Type.STRING },
        image_prompt: { type: Type.STRING },
      },
      required: ["page", "text", "image_prompt"]
    };

    // Strict schema matching the user's "STRICT OUTPUT FORMAT"
    const initialSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        story_info: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            language: { type: Type.STRING },
            age_group: { type: Type.STRING },
            art_style: { type: Type.STRING },
          },
          required: ["title", "language", "age_group", "art_style"]
        },
        characters: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
              personality: { type: Type.STRING },
              age: { type: Type.STRING },
              gender: { type: Type.STRING },
            },
            required: ["name", "description", "personality", "age", "gender"]
          }
        },
        pages: {
          type: Type.ARRAY,
          items: pageSchema
        }
      },
      required: ["story_info", "characters", "pages"]
    };

    const response = await this.ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: 'application/json',
        responseSchema: initialSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    let storyData: StoryData;
    try {
      const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsed = JSON.parse(cleanedText);

      // We manually inject aspect_ratio because the AI Strict JSON doesn't include it, but our UI needs it
      storyData = {
        ...parsed,
        story_info: {
          ...parsed.story_info,
          aspect_ratio: params.aspectRatio
        }
      };

    } catch (e) {
      console.error("Failed to parse story JSON", text);
      throw new Error("Failed to generate valid story structure.");
    }

    // Update progress based on initial batch
    const initialProgress = Math.min(100, Math.round((initialPageCount / totalPages) * 100));
    onProgress(initialProgress, `Generated ${initialPageCount} of ${totalPages} pages...`);

    // 2. Subsequent Batches Loop
    if (totalPages > BATCH_SIZE) {
       let currentPage = storyData.pages.length + 1;

       while (currentPage <= totalPages) {
           await this.checkPause();

           // --- Chapter Logic (Every 50 pages) ---
           const generatedCount = storyData.pages.length;
           if (generatedCount > 0 && generatedCount % 50 === 0) {
               const chapterNum = (generatedCount / 50) + 1;

               const chapterPage: StoryPage = {
                   page: currentPage,
                   text: `Chapter ${chapterNum}`,
                   image_prompt: `A decorative title page for Chapter ${chapterNum} of the story "${storyData.story_info.title}". ${storyData.story_info.art_style} style, elegant, magical typography, detailed background elements matching the story theme.`
               };

               storyData.pages.push(chapterPage);
               currentPage++;

               onProgress(
                   Math.round(((currentPage - 1) / totalPages) * 100), 
                   `Starting Chapter ${chapterNum}...`
               );

               // If adding the chapter page reached the total, stop here
               if (currentPage > totalPages) break;
           }
           // --------------------------------------

           const remaining = totalPages - currentPage + 1;
           const currentBatchSize = Math.min(remaining, BATCH_SIZE);
           const endPage = currentPage + currentBatchSize - 1;

           onProgress(
             Math.round(((currentPage - 1) / totalPages) * 100), 
             `Generating pages ${currentPage} to ${endPage}...`
           );

           const continuationPrompt = `
             You are continuing a children's story.

             Story Context:
             - Title: ${storyData.story_info.title}
             - Characters: ${storyData.characters.map(c => c.name).join(', ')}
             - Style: ${storyData.story_info.art_style}
             - Language: ${storyData.story_info.language}
             - Last Page (${currentPage-1}): "${storyData.pages[storyData.pages.length - 1].text}"

             TASK: Generate pages ${currentPage} to ${endPage}.

             RULES:
             1. Keep strict continuity in plot and character behavior.
             2. Maintain the same art style descriptions for image prompts.
             3. Output a valid JSON object with a "pages" array.
           `;

           const nextResponse = await this.ai.models.generateContent({
              model: 'gemini-3-flash-preview',
              contents: continuationPrompt,
              config: {
                  responseMimeType: 'application/json',
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          pages: {
                              type: Type.ARRAY,
                              items: pageSchema
                          }
                      }
                  }
              }
           });

           const nextText = nextResponse.text;
           if (nextText) {
               try {
                  const cleanedNextText = nextText.replace(/```json/g, '').replace(/```/g, '').trim();
                  const nextData = JSON.parse(cleanedNextText);
                  if (nextData.pages && Array.isArray(nextData.pages)) {
                      storyData.pages = [...storyData.pages, ...nextData.pages];
                  }
               } catch (e) {
                   console.error(`Failed to parse batch ${currentPage}-${endPage}`, e);
                   break;
               }
           }

           currentPage += currentBatchSize;
           const currentProgress = Math.min(100, Math.round(((currentPage - 1) / totalPages) * 100));
           onProgress(currentProgress, `Completed ${currentPage - 1} pages...`);
       }
    }

    onProgress(100, "Finalizing story...");
    return storyData;
  }
}

export const generateIllustration = async (prompt: string, aspectRatio: AspectRatio): Promise<string> => {
  const ai = getClient();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: prompt }] },
    config: { imageConfig: { aspectRatio: aspectRatio } }
  });

  const candidates = response.candidates;
  if (candidates?.[0]?.content?.parts) {
      for (const part of candidates[0].content.parts) {
          if (part.inlineData?.data) return part.inlineData.data;
      }
  }
  throw new Error("No image generated.");
};

export const regeneratePrompt = async (currentPrompt: string): Promise<string> => {
    const ai = getClient();
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Rewrite the following image prompt to change the camera angle or composition slightly, while keeping the subject and style exactly the same. Original: "${currentPrompt}". Return ONLY the new prompt text.`,
    });
    return response.text?.trim() || currentPrompt;
};

