import { GoogleGenAI, Type, Schema } from "@google/genai";
import { StoryData, StoryParams, AspectRatio, StoryPage } from "../types";
import { SYSTEM_INSTRUCTION } from "../constants";

// Helper to get client with key
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found. Please check your environment variables.");
  }
  return new GoogleGenAI({ apiKey });
};

const BATCH_SIZE = 20;

export class StoryGenerator {
  private isPaused = false;
  private resumeResolver: (() => void) | null = null;
  private ai = getClient();

  public pause() {
    this.isPaused = true;
  }

  public resume() {
    this.isPaused = false;
    if (this.resumeResolver) {
      this.resumeResolver();
      this.resumeResolver = null;
    }
  }

  private async checkPause() {
    if (this.isPaused) {
      await new Promise<void>((resolve) => {
        this.resumeResolver = resolve;
      });
    }
  }

  public async generate(
    params: StoryParams, 
    onProgress: (progress: number, message: string) => void
  ): Promise<StoryData> {
    const totalPages = params.pageCount;

    // 1. Initial Batch
    onProgress(10, "Designing characters and plot...");
    await this.checkPause();

    const initialPageCount = Math.min(totalPages, BATCH_SIZE);

    // Add specific description if Photorealistic Human Style is selected
    const artStyleDescription = params.artStyle === 'Photorealistic Human Style'
      ? 'Photorealistic Human Style (Ultra realistic lighting, skin texture, natural facial expressions)'
      : params.artStyle;

    // Strict prompt based on the user's setup requirements
    const prompt = `
      Create a children's story based on the following inputs:
      1. Story Idea: ${params.idea}
      2. Language: ${params.language}
      3. Age Group: ${params.ageGroup}
      4. Length: ${initialPageCount} pages ${totalPages > BATCH_SIZE ? `(Part 1 of ${totalPages})` : ''}
      5. Art Style: ${artStyleDescription}

      Follow all quality rules and strict JSON output format defined in the system instructions.
      Ensure you generate exactly ${initialPageCount} pages in this batch.
    `;

    const pageSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        page: { type: Type.INTEGER },
        text: { type: Type.STRING },
        image_prompt: { type: Type.STRING },
      },
      required: ["page", "text", "image_prompt"]
    };

    // Strict schema matching the user's "STRICT OUTPUT FORMAT"
    const initialSchema: Schema = {
      type: Type.OBJECT,
      properties: {
        story_info: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            language: { type: Type.STRING },
            age_group: { type: Type.STRING },
            art_style: { type: Type.STRING },
          },
          required: ["title", "language", "age_group", "art_style"]
        },
        characters: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
              personality: { type: Type.STRING },
              age: { type: Type.STRING },
              gender: { type: Type.STRING },
            },
            required: ["name", "description", "personality", "age", "gender"]
          }
        },
        pages: {
          type: Type.ARRAY,
          items: pageSchema
        }
      },
      required: ["story_info", "characters", "pages"]
    };

    const response = await this.ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: 'application/json',
        responseSchema: initialSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    let storyData: StoryData;
    try {
      const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsed = JSON.parse(cleanedText);

      // We manually inject aspect_ratio because the AI Strict JSON doesn't include it, but our UI needs it
      storyData = {
        ...parsed,
        story_info: {
          ...parsed.story_info,
          aspect_ratio: params.aspectRatio
        }
      };

    } catch (e) {
      console.error("Failed to parse story JSON", text);
      throw new Error("Failed to generate valid story structure.");
    }

    // Update progress based on initial batch
    const initialProgress = Math.min(100, Math.round((initialPageCount / totalPages) * 100));
    onProgress(initialProgress, `Generated ${initialPageCount} of ${totalPages} pages...`);

    // 2. Subsequent Batches Loop
    if (totalPages > BATCH_SIZE) {
       let currentPage = storyData.pages.length + 1;

       while (currentPage <= totalPages) {
           await this.checkPause();

           // --- Chapter Logic (Every 50 pages) ---
           const generatedCount = storyData.pages.length;
           if (generatedCount > 0 && generatedCount % 50 === 0) {
               const chapterNum = (generatedCount / 50) + 1;

               const chapterPage: StoryPage = {
                   page: currentPage,
                   text: `Chapter ${chapterNum}`,
                   image_prompt: `A decorative title page for Chapter ${chapterNum} of the story "${storyData.story_info.title}". ${storyData.story_info.art_style} style, elegant, magical typography, detailed background elements matching the story theme.`
               };

               storyData.pages.push(chapterPage);
               currentPage++;

               onProgress(
                   Math.round(((currentPage - 1) / totalPages) * 100), 
                   `Starting Chapter ${chapterNum}...`
               );

               // If adding the chapter page reached the total, stop here
               if (currentPage > totalPages) break;
           }
           // --------------------------------------

           const remaining = totalPages - currentPage + 1;
           const currentBatchSize = Math.min(remaining, BATCH_SIZE);
           const endPage = currentPage + currentBatchSize - 1;

           onProgress(
             Math.round(((currentPage - 1) / totalPages) * 100), 
             `Generating pages ${currentPage} to ${endPage}...`
           );

           const continuationPrompt = `
             You are continuing a children's story.

             Story Context:
             - Title: ${storyData.story_info.title}
             - Characters: ${storyData.characters.map(c => c.name).join(', ')}
             - Style: ${storyData.story_info.art_style}
             - Language: ${storyData.story_info.language}
             - Last Page (${currentPage-1}): "${storyData.pages[storyData.pages.length - 1].text}"

             TASK: Generate pages ${currentPage} to ${endPage}.

             RULES:
             1. Keep strict continuity in plot and character behavior.
             2. Maintain the same art style descriptions for image prompts.
             3. Output a valid JSON object with a "pages" array.
           `;

           const nextResponse = await this.ai.models.generateContent({
              model: 'gemini-3-flash-preview',
              contents: continuationPrompt,
              config: {
                  responseMimeType: 'application/json',
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          pages: {
                              type: Type.ARRAY,
                              items: pageSchema
                          }
                      }
                  }
              }
           });

           const nextText = nextResponse.text;
           if (nextText) {
               try {
                  const cleanedNextText = nextText.replace(/```json/g, '').replace(/```/g, '').trim();
                  const nextData = JSON.parse(cleanedNextText);
                  if (nextData.pages && Array.isArray(nextData.pages)) {
                      storyData.pages = [...storyData.pages, ...nextData.pages];
                  }
               } catch (e) {
                   console.error(`Failed to parse batch ${currentPage}-${endPage}`, e);
                   break;
               }
           }

           currentPage += currentBatchSize;
           const currentProgress = Math.min(100, Math.round(((currentPage - 1) / totalPages) * 100));
           onProgress(currentProgress, `Completed ${currentPage - 1} pages...`);
       }
    }

    onProgress(100, "Finalizing story...");
    return storyData;
  }
}

export const generateIllustration = async (prompt: string, aspectRatio: AspectRatio): Promise<string> => {
  const ai = getClient();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts: [{ text: prompt }] },
    config: { imageConfig: { aspectRatio: aspectRatio } }
  });

  const candidates = response.candidates;
  if (candidates?.[0]?.content?.parts) {
      for (const part of candidates[0].content.parts) {
          if (part.inlineData?.data) return part.inlineData.data;
      }
  }
  throw new Error("No image generated.");
};

export const regeneratePrompt = async (currentPrompt: string): Promise<string> => {
    const ai = getClient();
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Rewrite the following image prompt to change the camera angle or composition slightly, while keeping the subject and style exactly the same. Original: "${currentPrompt}". Return ONLY the new prompt text.`,
    });
    return response.text?.trim() || currentPrompt;
};

import React, { useState, useEffect } from 'react';
import { ArrowLeft, ArrowRight, RefreshCw, Download, Save, Wand2, FileText, Images, Share2, CheckCircle, Clock } from 'lucide-react';
import { StoryData, StoryPage, AspectRatio } from '../types';
import { generateIllustration, regeneratePrompt } from '../services/gemini';
import { jsPDF } from "jspdf";
import JSZip from "jszip";
import saveAs from "file-saver";

interface StoryBookProps {
  story: StoryData;
  onReset: () => void;
}

const StoryBook: React.FC<StoryBookProps> = ({ story, onReset }) => {
  const [currentPageIndex, setCurrentPageIndex] = useState(0);
  const [pages, setPages] = useState<StoryPage[]>(story.pages);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  const isRTL = story.story_info.language === 'Arabic';
  const currentPage = pages[currentPageIndex];

  // Use aspect ratio from story info, default to 16:9 if missing
  const aspectRatio: AspectRatio = (story.story_info.aspect_ratio as AspectRatio) || '16:9';
  const isVertical = aspectRatio === '9:16';

  // Check if all images are generated
  const allImagesReady = pages.every(p => p.generatedImage);

  const getArtStyleDescription = (style: string) => {
    if (style === 'Photorealistic Human Style') {
      return 'Photorealistic Human Style (Ultra realistic lighting, skin texture, natural facial expressions)';
    }
    return style;
  };

  // Auto-generate image for the current page if missing
  useEffect(() => {
    const generateForPage = async () => {
      if (!currentPage.generatedImage && !currentPage.isGeneratingImage) {

        // Mark as generating
        setPages(prev => prev.map((p, idx) => 
          idx === currentPageIndex ? { ...p, isGeneratingImage: true } : p
        ));

        try {
          // Construct a full prompt using character info for consistency
          const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
          ).join(' ');

          const fullPrompt = `Art Style: ${getArtStyleDescription(story.story_info.art_style)}. ${characterContext} Scene: ${currentPage.image_prompt}`;

          const base64Image = await generateIllustration(fullPrompt, aspectRatio);

          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
          ));

        } catch (error) {
          console.error("Failed to generate image", error);
          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
          ));
        }
      }
    };

    generateForPage();
  }, [currentPageIndex, currentPage.generatedImage, currentPage.isGeneratingImage, currentPage.image_prompt, story.characters, story.story_info.art_style, aspectRatio]);

  const handleNext = () => {
    if (currentPageIndex < pages.length - 1) {
      setCurrentPageIndex(prev => prev + 1);
    }
  };

  const handlePrev = () => {
    if (currentPageIndex > 0) {
      setCurrentPageIndex(prev => prev - 1);
    }
  };

  const handleRegenerateImage = async () => {
    if (isGeneratingImage) return;
    setIsGeneratingImage(true);

    // Clear current image and mark generating
    setPages(prev => prev.map((p, idx) => 
        idx === currentPageIndex ? { ...p, generatedImage: undefined, isGeneratingImage: true } : p
    ));

    try {
        // Step 1: Rewrite prompt
        const newPrompt = await regeneratePrompt(currentPage.image_prompt);

        // Update prompt in state
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, image_prompt: newPrompt } : p
        ));

        // Step 2: Generate new image
        const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
        ).join(' ');
        const fullPrompt = `Art Style: ${getArtStyleDescription(story.story_info.art_style)}. ${characterContext} Scene: ${newPrompt}`;

        const base64Image = await generateIllustration(fullPrompt, aspectRatio);

        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
        ));

    } catch (e) {
        console.error("Regeneration failed", e);
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
        ));
    } finally {
        setIsGeneratingImage(false);
    }
  };

  const handleSaveJSON = () => {
    const cleanPages = pages.map(({ isGeneratingImage, ...rest }) => rest);

    const storyData = {
      ...story,
      pages: cleanPages,
      savedAt: new Date().toISOString()
    };

    try {
      localStorage.setItem("sawan_story", JSON.stringify(storyData));
      alert(isRTL ? "✅ تم حفظ القصة بنجاح!" : "✅ Story saved successfully!");
    } catch (e) {
      console.warn("LocalStorage quota exceeded or error, falling back to download", e);

      const jsonString = JSON.stringify(storyData, null, 2);
      const blob = new Blob([jsonString], { type: "application/json" });
      saveAs(blob, `${story.story_info.title.replace(/\s+/g, "_") || "story"}.json`);

      alert(isRTL ? "القصة كبيرة جداً للحفظ في المتصفح. تم تنزيلها كملف بدلاً من ذلك." : "Story is too large for browser storage. Downloaded as file instead.");
    }
    setShowExportMenu(false);
  };

  const handleDownloadPDF = () => {
    try {
        // A4 size: 210 x 297 mm
        const doc = new jsPDF({
            orientation: isVertical ? 'portrait' : 'landscape',
            unit: 'mm',
            format: 'a4'
        });

        // Cover Page
        doc.setFontSize(24);
        doc.text(story.story_info.title, 105, 100, { align: 'center' });
        doc.setFontSize(16);
        doc.text(`A story for ${story.story_info.age_group} year olds`, 105, 120, { align: 'center' });

        pages.forEach((page, index) => {
            doc.addPage();

            // Image
            if (page.generatedImage) {
                // Keep aspect ratio
                const imgData = `data:image/jpeg;base64,${page.generatedImage}`;
                const pageWidth = doc.internal.pageSize.getWidth();
                const pageHeight = doc.internal.pageSize.getHeight();

                let imgWidth, imgHeight, x, y;

                if (isVertical) {
                   // Portrait layout
                   imgWidth = pageWidth - 40; // 20mm margins
                   imgHeight = imgWidth * (16/9); 
                   x = 20;
                   y = 20;
                   // Ensure it fits
                   if (imgHeight > pageHeight * 0.6) {
                       imgHeight = pageHeight * 0.6;
                       imgWidth = imgHeight * (9/16);
                       x = (pageWidth - imgWidth) / 2;
                   }
                } else {
                   // Landscape layout
                   imgHeight = pageHeight * 0.6;
                   imgWidth = imgHeight * (16/9);
                   x = (pageWidth - imgWidth) / 2;
                   y = 20;
                }

                try {
                    doc.addImage(imgData, 'JPEG', x, y, imgWidth, imgHeight);
                } catch (err) {
                    console.error("Error adding image to PDF", err);
                }

                // Text
                doc.setFontSize(14);
                // Split text to fit width
                const textWidth = 170; // mm
                const splitText = doc.splitTextToSize(page.text, textWidth);

                let textY = y + imgHeight + 20;
                // Check if text fits
                if (textY + (splitText.length * 7) > pageHeight) {
                    doc.addPage();
                    textY = 20;
                }

                doc.text(splitText, pageWidth / 2, textY, { align: 'center' });
            } else {
                doc.setFontSize(14);
                const splitText = doc.splitTextToSize(page.text, 170);
                doc.text(splitText, 105, 50, { align: 'center' });
            }

            // Page Number
            doc.setFontSize(10);
            doc.text(`${index + 1}`, 200, 287, { align: 'right' });
