import React, { useState, useEffect } from 'react';
import { ArrowLeft, ArrowRight, RefreshCw, Download, Save, Wand2, FileText, Images, Share2, CheckCircle, Clock, Video, Copy, Volume2, Facebook, Youtube, Send, Phone } from 'lucide-react';
import { StoryData, StoryPage, AspectRatio } from '../types';
import { generateIllustration, regeneratePrompt } from '../services/gemini';
import { jsPDF } from "jspdf";
import JSZip from "jszip";
import saveAs from "file-saver";

interface StoryBookProps {
  story: StoryData;
  onReset: () => void;
}

const StoryBook: React.FC<StoryBookProps> = ({ story, onReset }) => {
  const [currentPageIndex, setCurrentPageIndex] = useState(0);
  const [pages, setPages] = useState<StoryPage[]>(story.pages);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // Voice State
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [voiceSpeed, setVoiceSpeed] = useState(1);

  const isRTL = story.story_info.language === 'Arabic';
  const currentPage = pages[currentPageIndex];

  // Use aspect ratio from story info, default to 16:9 if missing
  const aspectRatio: AspectRatio = (story.story_info.aspect_ratio as AspectRatio) || '16:9';
  const isVertical = aspectRatio === '9:16';

  // Check if all images are generated
  const allImagesReady = pages.every(p => p.generatedImage);

  const getArtStyleDescription = (style: string) => {
    if (style === 'Photorealistic Human Style') {
      return 'Photorealistic Human Style (Ultra realistic lighting, skin texture, natural facial expressions)';
    }
    return style;
  };

  // Stop speech when page changes
  useEffect(() => {
    window.speechSynthesis.cancel();
    setIsSpeaking(false);
  }, [currentPageIndex]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      window.speechSynthesis.cancel();
    };
  }, []);

  // Auto-generate image for the current page if missing
  useEffect(() => {
    const generateForPage = async () => {
      if (!currentPage.generatedImage && !currentPage.isGeneratingImage) {

        // Mark as generating
        setPages(prev => prev.map((p, idx) => 
          idx === currentPageIndex ? { ...p, isGeneratingImage: true } : p
        ));

        try {
          // Construct a full prompt using character info for consistency
          const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
          ).join(' ');

          const fullPrompt = `Art Style: ${getArtStyleDescription(story.story_info.art_style)}. ${characterContext} Scene: ${currentPage.image_prompt}`;

          const base64Image = await generateIllustration(fullPrompt, aspectRatio);

          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
          ));

        } catch (error) {
          console.error("Failed to generate image", error);
          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
          ));
        }
      }
    };

    generateForPage();
  }, [currentPageIndex, currentPage.generatedImage, currentPage.isGeneratingImage, currentPage.image_prompt, story.characters, story.story_info.art_style, aspectRatio]);

  const handleNext = () => {
    if (currentPageIndex < pages.length - 1) {
      setCurrentPageIndex(prev => prev + 1);
    }
  };

  const handlePrev = () => {
    if (currentPageIndex > 0) {
      setCurrentPageIndex(prev => prev - 1);
    }
  };

  const handleRegenerateImage = async () => {
    if (isGeneratingImage) return;
    setIsGeneratingImage(true);

    // Clear current image and mark generating
    setPages(prev => prev.map((p, idx) => 
        idx === currentPageIndex ? { ...p, generatedImage: undefined, isGeneratingImage: true } : p
    ));

    try {
        // Step 1: Rewrite prompt
        const newPrompt = await regeneratePrompt(currentPage.image_prompt);

        // Update prompt in state
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, image_prompt: newPrompt } : p
        ));

        // Step 2: Generate new image
        const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
        ).join(' ');
        const fullPrompt = `Art Style: ${getArtStyleDescription(story.story_info.art_style)}. ${characterContext} Scene: ${newPrompt}`;

        const base64Image = await generateIllustration(fullPrompt, aspectRatio);

        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
        ));

    } catch (e) {
        console.error("Regeneration failed", e);
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
        ));
    } finally {
        setIsGeneratingImage(false);
    }
  };

  const handleSaveJSON = () => {
    const cleanPages = pages.map(({ isGeneratingImage, ...rest }) => rest);

    const storyData = {
      ...story,
      pages: cleanPages,
      savedAt: new Date().toISOString()
    };

    try {
      localStorage.setItem("sawan_story", JSON.stringify(storyData));
      alert(isRTL ? "✅ تم حفظ القصة بنجاح!" : "✅ Story saved successfully!");
    } catch (e) {
      console.warn("LocalStorage quota exceeded or error, falling back to download", e);

      const jsonString = JSON.stringify(storyData, null, 2);
      const blob = new Blob([jsonString], { type: "application/json" });
      saveAs(blob, `${story.story_info.title.replace(/\s+/g, "_") || "story"}.json`);

      alert(isRTL ? "القصة كبيرة جداً للحفظ في المتصفح. تم تنزيلها كملف بدلاً من ذلك." : "Story is too large for browser storage. Downloaded as file instead.");
    }
    setShowExportMenu(false);
  };

  const handleDownloadPDF = () => {
    try {
        // A4 size: 210 x 297 mm
        const doc = new jsPDF({
            orientation: isVertical ? 'portrait' : 'landscape',
            unit: 'mm',
            format: 'a4'
        });

        // Cover Page
        doc.setFontSize(24);
        doc.text(story.story_info.title, 105, 100, { align: 'center' });
        doc.setFontSize(16);
        doc.text(`A story for ${story.story_info.age_group} year olds`, 105, 120, { align: 'center' });

        pages.forEach((page, index) => {
            doc.addPage();

            // Image
            if (page.generatedImage) {
                // Keep aspect ratio
                const imgData = `data:image/jpeg;base64,${page.generatedImage}`;
                const pageWidth = doc.internal.pageSize.getWidth();
                const pageHeight = doc.internal.pageSize.getHeight();

                let imgWidth, imgHeight, x, y;

                if (isVertical) {
                   // Portrait layout
                   imgWidth = pageWidth - 40; // 20mm margins
                   imgHeight = imgWidth * (16/9); 
                   x = 20;
                   y = 20;
                   // Ensure it fits
                   if (imgHeight > pageHeight * 0.6) {
                       imgHeight = pageHeight * 0.6;
                       imgWidth = imgHeight * (9/16);
                       x = (pageWidth - imgWidth) / 2;
                   }
                } else {
                   // Landscape layout
                   imgHeight = pageHeight * 0.6;
                   imgWidth = imgHeight * (16/9);
                   x = (pageWidth - imgWidth) / 2;
                   y = 20;
                }

                try {
                    doc.addImage(imgData, 'JPEG', x, y, imgWidth, imgHeight);
                } catch (err) {
                    console.error("Error adding image to PDF", err);
                }

                // Text
                doc.setFontSize(14);
                // Split text to fit width
                const textWidth = 170; // mm
                const splitText = doc.splitTextToSize(page.text, textWidth);

                let textY = y + imgHeight + 20;
                // Check if text fits
                if (textY + (splitText.length * 7) > pageHeight) {
                    doc.addPage();
                    textY = 20;
                }

                doc.text(splitText, pageWidth / 2, textY, { align: 'center' });
            } else {
                doc.setFontSize(14);
                const splitText = doc.splitTextToSize(page.text, 170);
                doc.text(splitText, 105, 50, { align: 'center' });
            }

            // Page Number
            doc.setFontSize(10);
            doc.text(`${index + 1}`, 200, 287, { align: 'right' });
        });

        doc.save(`${story.story_info.title || "story"}.pdf`);
    } catch (e) {
        console.error("PDF Export failed", e);
        alert("Could not generate PDF. Please ensure all images are loaded.");
    }
    setShowExportMenu(false);
  };

  const handleDownloadImages = async () => {
    const zip = new JSZip();
    const folder = zip.folder("story-images");

    let count = 0;
    pages.forEach((page, i) => {
        if (page.generatedImage) {
            folder?.file(`page-${i + 1}.jpg`, page.generatedImage, { base64: true });
            count++;
        }
    });

    if (count === 0) {
        alert("No images generated yet!");
        return;
    }

    try {
        const content = await zip.generateAsync({ type: "blob" });
        saveAs(content, `${story.story_info.title || "story"}_images.zip`);
    } catch (e) {
        console.error("Zip generation failed", e);
    }
    setShowExportMenu(false);
  };

  /* ================= SAWAN EXTENSIONS LOGIC ================= */

  // 1. Copy Animation Prompt
  const copyAnimationPrompt = () => {
    const prompt = `
Animate the image with smooth cinematic motion.

Rules:
- NO music.
- NO dialogue or spoken words.
- Characters must NOT speak or lip-sync.

Allowed audio:
- Natural sound effects only.
- Light laughter is allowed.
- Soft crying or emotional breathing is allowed.
- Ambient environment sounds.

Animation:
- Subtle realistic body movement.
- Natural breathing.
- Gentle head and eye motion.
- Emotional expressions without speech.

Camera:
- Smooth cinematic movement.

Result:
- Silent characters.
- Emotional animation.
    `;
    navigator.clipboard.writeText(prompt.trim());
    alert(isRTL ? "✅ تم نسخ برومبت التحريك" : "✅ Animation prompt copied!");
  };

  // 2. Voice / Text-to-Speech
  const handlePlayVoice = () => {
    if (isSpeaking) {
      window.speechSynthesis.cancel();
      setIsSpeaking(false);
      return;
    }

    const utterance = new SpeechSynthesisUtterance(currentPage.text);
    utterance.lang = isRTL ? 'ar-SA' : 'en-US';
    utterance.rate = voiceSpeed;

    // Attempt to select a better voice if available
    const voices = window.speechSynthesis.getVoices();
    let preferredVoice = null;

    if (isRTL) {
        // Try to find a specific Arabic voice (Google or just 'ar')
        preferredVoice = voices.find(v => v.lang === 'ar-SA' || v.lang.startsWith('ar'));
    } else {
        preferredVoice = voices.find(v => v.lang === 'en-US' && v.name.includes('Google'));
    }

    if (preferredVoice) utterance.voice = preferredVoice;

    utterance.onend = () => setIsSpeaking(false);

    window.speechSynthesis.speak(utterance);
    setIsSpeaking(true);
  };

  const handleDownloadVoice = () => {
    // Note: Direct download from speech API isn't supported in browsers. 
    // Fallback to the link method suggested in the snippet for "External" TTS services
    const text = encodeURIComponent(currentPage.text);
    const url = `https://translate.google.com/translate_tts?ie=UTF-8&q=${text}&tl=${isRTL ? 'ar' : 'en'}&client=tw-ob`;
    window.open(url, '_blank');
  };

  // 3. Sharing
  const handleShareWhatsapp = () => {
    const text = encodeURIComponent(`${story.story_info.title}\n\n${currentPage.text}`);
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  const handleShareFacebook = () => {
    window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent('https://www.facebook.com/AhmedSawanOfficial/')}`, '_blank');
  };

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-[#0f172a] text-slate-100 font-sans transition-colors duration-300">

      {/* Header */}
      <header className="flex items-center justify-between p-4 border-b border-slate-800 bg-[#0f172a] z-20 relative">
        <button onClick={onReset} className="flex items-center text-slate-400 hover:text-white transition-colors font-bold">
          {isRTL ? <ArrowRight className="w-5 h-5 ms-2" /> : <ArrowLeft className="w-5 h-5 me-2" />}
          {isRTL ? "الرئيسية" : "Home"}
        </button>
        <h1 className={`text-lg md:text-xl font-heading font-bold text-white truncate px-4 ${isRTL ? 'font-arabic' : ''}`} id="storyTitle">
          {story.story_info.title}
        </h1>

        {/* Actions Menu (Header) */}
        <div className="relative">
            <button 
                onClick={() => setShowExportMenu(!showExportMenu)}
                className="flex items-center text-brand-400 hover:text-brand-300 transition-colors font-bold gap-2 px-3 py-2 rounded-lg hover:bg-slate-800"
            >
                <Share2 className="w-5 h-5" />
                <span className="hidden md:inline">{isRTL ? "تصدير" : "Export"}</span>
            </button>

            {/* Dropdown */}
            {showExportMenu && (
                <div className="absolute right-0 rtl:right-auto rtl:left-0 top-full mt-2 w-56 bg-slate-800 border border-slate-700 rounded-xl shadow-2xl overflow-hidden z-50">
                    <button onClick={handleSaveJSON} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-700 text-left rtl:text-right text-slate-200 transition-colors">
                        <Save className="w-4 h-4 text-green-400" />
                        <span>{isRTL ? "حفظ المشروع" : "Save Project (JSON)"}</span>
                    </button>
                    <button onClick={handleDownloadPDF} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-700 text-left rtl:text-right text-slate-200 transition-colors border-t border-slate-700">
                        <FileText className="w-4 h-4 text-red-400" />
                        <span>{isRTL ? "تنزيل PDF" : "Download PDF"}</span>
                    </button>
                    <button onClick={handleDownloadImages} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-700 text-left rtl:text-right text-slate-200 transition-colors border-t border-slate-700">
                        <Images className="w-4 h-4 text-blue-400" />
                        <span>{isRTL ? "تنزيل الصور" : "Download Images (ZIP)"}</span>
                    </button>
                </div>
            )}
        </div>
      </header>

      {/* Overlay to close menu */}
      {showExportMenu && (
          <div className="fixed inset-0 z-10" onClick={() => setShowExportMenu(false)}></div>
      )}

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col items-center justify-start p-4 md:p-6 overflow-y-auto scrollbar-thin scrollbar-thumb-slate-700">

        {/* Story Card */}
        <div className={`
          w-full bg-slate-900 rounded-2xl shadow-2xl flex flex-col md:flex-row overflow-hidden border border-slate-800 relative transition-all duration-300 shrink-0
          ${isVertical ? 'max-w-2xl min-h-[600px]' : 'max-w-7xl min-h-[500px]'}
        `}>

          {/* Text Side */}
          <div className="flex-1 p-8 md:p-12 flex flex-col justify-center items-start overflow-y-auto z-10 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
            <div className="w-full flex flex-col justify-center">
                <span className="text-slate-700 font-heading font-bold text-6xl opacity-30 mb-4 select-none">
                    {currentPage.page}
                </span>
                <p className={`text-2xl md:text-3xl leading-relaxed text-slate-200 font-medium ${isRTL ? 'font-arabic' : 'font-heading'}`}>
                {currentPage.text}
                </p>
            </div>
          </div>

          {/* Image Side */}
          <div className={`
            relative bg-black flex items-center justify-center
            ${isVertical ? 'flex-1 h-[400px] md:h-auto md:w-1/2 order-first md:order-last border-b md:border-b-0 md:border-l border-slate-800' : 'flex-1 h-[300px] md:h-auto border-t md:border-t-0 md:border-l rtl:md:border-l-0 rtl:md:border-r border-slate-800'}
          `}>
            {currentPage.generatedImage ? (
                <>
                    <img 
                        src={`data:image/jpeg;base64,${currentPage.generatedImage}`} 
                        alt={currentPage.image_prompt}
                        className="w-full h-full object-contain"
                    />
                    <div className="absolute top-4 right-4 rtl:left-4 rtl:right-auto flex gap-2">
                        <a 
                            href={`data:image/jpeg;base64,${currentPage.generatedImage}`} 
                            download={`story_page_${currentPage.page}.jpg`}
                            className="bg-black/50 hover:bg-black/70 backdrop-blur-sm p-2 rounded-full text-white transition-all flex items-center justify-center border border-white/10"
                            title="Download Image"
                        >
                            <Download className="w-5 h-5" />
                        </a>
                        <button 
                            onClick={handleRegenerateImage}
                            disabled={currentPage.isGeneratingImage}
                            className="bg-black/50 hover:bg-black/70 backdrop-blur-sm p-2 rounded-full text-white transition-all border border-white/10"
                            title="Regenerate Image"
                        >
                            <RefreshCw className={`w-5 h-5 ${currentPage.isGeneratingImage ? 'animate-spin' : ''}`} />
                        </button>
                    </div>
                </>
            ) : (
                <div className="flex flex-col items-center p-8 text-center animate-pulse">
                    <Wand2 className="w-16 h-16 text-brand-500 mb-4 animate-bounce" />
                    <p className="text-slate-300 font-heading text-lg">
                        {isRTL ? "جارٍ رسم المشهد..." : "Painting this page..."}
                    </p>
                    <p className="text-slate-500 text-sm mt-2 max-w-xs">{currentPage.image_prompt.substring(0, 100)}...</p>
                </div>
            )}
          </div>
        </div>

        {/* Story Actions (Original) */}
        <div className="mt-8 w-full max-w-4xl animate-fade-in" id="storyActions">
            <div className="flex flex-col items-center justify-center gap-4">

                <p className={`text-sm font-bold flex items-center gap-2 ${allImagesReady ? 'text-green-400' : 'text-slate-400'}`} id="storyNotice">
                   {allImagesReady ? (
                       <>
                           <CheckCircle className="w-4 h-4" />
                           {isRTL ? "✅ القصة جاهزة! يمكنك الآن الحفظ أو التحميل" : "✅ The story is ready! You can now save or download."}
                       </>
                   ) : (
                       <>
                           <Clock className="w-4 h-4" />
                           {isRTL 
                             ? "⏳ سيتم تفعيل خيارات الحفظ والتحميل الكاملة بعد توليد جميع صور القصة" 
                             : "⏳ Download options will be fully ready after all story images are generated."}
                       </>
                   )}
                </p>

                <div className="flex flex-wrap gap-3 justify-center">
                    <button 
                        onClick={handleSaveJSON}
                        className="px-5 py-3 rounded-xl border-none cursor-pointer bg-sky-400 text-slate-950 font-bold hover:bg-sky-300 transition-colors flex items-center gap-2 shadow-lg hover:shadow-sky-400/20"
                    >
                        <Save className="w-5 h-5" />
                        {isRTL ? "حفظ القصة" : "Save Story"}
                    </button>

                    <button 
                        onClick={handleDownloadPDF}
                        className="px-5 py-3 rounded-xl border-none cursor-pointer bg-green-500 text-green-950 font-bold hover:bg-green-400 transition-colors flex items-center gap-2 shadow-lg hover:shadow-green-500/20"
                    >
                        <FileText className="w-5 h-5" />
                        {isRTL ? "تنزيل PDF" : "Download PDF"}
                    </button>

                    <button 
                        onClick={handleDownloadImages}
                        className="px-5 py-3 rounded-xl border-none cursor-pointer bg-yellow-400 text-yellow-950 font-bold hover:bg-yellow-300 transition-colors flex items-center gap-2 shadow-lg hover:shadow-yellow-400/20"
                    >
                        <Images className="w-5 h-5" />
                        {isRTL ? "تنزيل الصور" : "Download Images"}
                    </button>
                </div>
            </div>
        </div>

        {/* SAWAN STUDIO EXTENSIONS */}
        <div className="mt-8 w-full max-w-4xl grid grid-cols-1 md:grid-cols-3 gap-4">

          {/* 🎬 Animation Prompt */}
          <div className="bg-slate-800/50 rounded-2xl p-4 border border-slate-700 flex flex-col gap-3">
             <div className="flex items-center gap-2 text-purple-400 font-bold mb-1">
                <Video className="w-5 h-5" />
                <h3>{isRTL ? "تحريك الصورة" : "Animate Image"}</h3>
             </div>
             <p className="text-xs text-slate-400">{isRTL ? "نسخ وصف جاهز لتحريك الصورة في أدوات الفيديو" : "Copy prompt for video generation tools"}</p>
             <button 
               onClick={copyAnimationPrompt}
               className="mt-auto w-full py-2 bg-purple-600 hover:bg-purple-500 rounded-lg font-bold flex items-center justify-center gap-2 transition-colors text-sm"
             >
               <Copy className="w-4 h-4" />
               {isRTL ? "نسخ البرومبت" : "Copy Prompt"}
             </button>
          </div>

          {/* 🔊 Voice Story */}
          <div className="bg-slate-800/50 rounded-2xl p-4 border border-slate-700 flex flex-col gap-3">
             <div className="flex items-center gap-2 text-pink-400 font-bold mb-1">
                <Volume2 className="w-5 h-5" />
                <h3>{isRTL ? "اسمع القصة" : "Listen to Story"}</h3>
             </div>

             <div className="flex gap-2 text-slate-900">
               <select 
                 value={voiceSpeed}
                 onChange={(e) => setVoiceSpeed(parseFloat(e.target.value))}
                 className="flex-1 rounded-lg text-sm p-2 bg-slate-200 border-none outline-none cursor-pointer font-bold"
               >
                 <option value="0.8">{isRTL ? "بطيء" : "Slow"}</option>
                 <option value="1">{isRTL ? "متوسط" : "Normal"}</option>
                 <option value="1.5">{isRTL ? "سريع" : "Fast"}</option>
               </select>
             </div>

             <div className="flex gap-2 mt-auto">
                <button 
                  onClick={handlePlayVoice}
                  className={`flex-1 py-2 rounded-lg font-bold flex items-center justify-center gap-2 transition-colors text-sm ${isSpeaking ? 'bg-red-500 hover:bg-red-400' : 'bg-pink-600 hover:bg-pink-500'}`}
                >
                  <Volume2 className="w-4 h-4" />
                  {isSpeaking ? (isRTL ? "إيقاف" : "Stop") : (isRTL ? "تشغيل" : "Play")}
                </button>
                <button 
                  onClick={handleDownloadVoice}
                  className="flex-1 py-2 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2 transition-colors text-sm"
                >
                  <Download className="w-4 h-4" />
                  {isRTL ? "تحميل" : "Download"}
                </button>
             </div>
          </div>

          {/* 🔗 Share */}
          <div className="bg-slate-800/50 rounded-2xl p-4 border border-slate-700 flex flex-col gap-3">
             <div className="flex items-center gap-2 text-green-400 font-bold mb-1">
                <Share2 className="w-5 h-5" />
                <h3>{isRTL ? "مشاركة القصة" : "Share Story"}</h3>
             </div>
             <p className="text-xs text-slate-400">{isRTL ? "شارك نص الصفحة الحالية" : "Share current page text"}</p>
             <div className="flex gap-2 mt-auto">
                <button 
                  onClick={handleShareWhatsapp}
                  className="flex-1 py-2 bg-green-600 hover:bg-green-500 rounded-lg font-bold flex items-center justify-center gap-2 transition-colors text-sm"
                >
                  <Phone className="w-4 h-4" />
                  WhatsApp
                </button>
                <button 
                  onClick={handleShareFacebook}
                  className="flex-1 py-2 bg-blue-600 hover:bg-blue-500 rounded-lg font-bold flex items-center justify-center gap-2 transition-colors text-sm"
                >
                  <Facebook className="w-4 h-4" />
                  FB
                </button>
             </div>
          </div>

        </div>

        {/* SAWAN SOCIAL FOOTER */}
        <div className="mt-12 mb-4 flex items-center justify-center gap-6 opacity-70 hover:opacity-100 transition-opacity">
           <a href="https://www.youtube.com/@SawanAiOfficial" target="_blank" rel="noopener noreferrer" className="p-2 bg-slate-800 rounded-full hover:scale-110 transition-transform text-red-500 hover:bg-slate-700">
             <Youtube className="w-6 h-6" />
           </a>
           <a href="https://www.facebook.com/AhmedSawanOfficial/" target="_blank" rel="noopener noreferrer" className="p-2 bg-slate-800 rounded-full hover:scale-110 transition-transform text-blue-500 hover:bg-slate-700">
             <Facebook className="w-6 h-6" />
           </a>
           <a href="https://t.me/AhmedMSawan" target="_blank" rel="noopener noreferrer" className="p-2 bg-slate-800 rounded-full hover:scale-110 transition-transform text-sky-500 hover:bg-slate-700">
             <Send className="w-6 h-6" />
           </a>
           <a href="https://api.whatsapp.com/send/?phone=201000150303" target="_blank" rel="noopener noreferrer" className="p-2 bg-slate-800 rounded-full hover:scale-110 transition-transform text-green-500 hover:bg-slate-700">
             <Phone className="w-6 h-6" />
           </a>
        </div>

      </main>

      {/* Footer Navigation */}
      <footer className="p-6 border-t border-slate-800 bg-[#0f172a] flex items-center justify-between z-20">
        <button 
            onClick={handlePrev} 
            disabled={currentPageIndex === 0}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === 0 
                ? 'text-slate-700 cursor-not-allowed' 
                : 'bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white border border-slate-700'
            }`}
        >
            {isRTL ? <ArrowRight className="w-5 h-5 ms-2" /> : <ArrowLeft className="w-5 h-5 me-2" />}
            {isRTL ? "السابق" : "Previous"}
        </button>

        <div className="hidden md:flex gap-2">
            {pages.map((_, idx) => (
                <div 
                    key={idx}
                    className={`w-2.5 h-2.5 rounded-full transition-all ${
                        idx === currentPageIndex ? 'bg-brand-500 scale-125' : 'bg-slate-700'
                    }`}
                />
            ))}
        </div>
        <div className="md:hidden text-slate-500 font-bold">
            {currentPageIndex + 1} / {pages.length}
        </div>

        <button 
            onClick={handleNext} 
            disabled={currentPageIndex === pages.length - 1}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === pages.length - 1 
                ? 'text-slate-700 cursor-not-allowed' 
                : 'bg-brand-600 text-white hover:bg-brand-500 shadow-lg shadow-brand-900/20'
            }`}
        >
            {isRTL ? "التالي" : "Next"}
            {isRTL ? <ArrowLeft className="w-5 h-5 me-2" /> : <ArrowRight className="w-5 h-5 ms-2" />}
        </button>
      </footer>
    </div>
  );
};

export default StoryBook;

import React, { useState, useEffect } from 'react';
import { ArrowLeft, ArrowRight, RefreshCw, Download, Save, Wand2, FileText, Images, Share2, CheckCircle, Clock, Video, Copy, Volume2, Facebook, Youtube, Send, Phone } from 'lucide-react';
import { StoryData, StoryPage, AspectRatio } from '../types';
import { generateIllustration, regeneratePrompt } from '../services/gemini';
import { jsPDF } from "jspdf";
import JSZip from "jszip";
import saveAs from "file-saver";

interface StoryBookProps {
  story: StoryData;
  onReset: () => void;
}

const StoryBook: React.FC<StoryBookProps> = ({ story, onReset }) => {
  const [currentPageIndex, setCurrentPageIndex] = useState(0);
  const [pages, setPages] = useState<StoryPage[]>(story.pages);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  // Voice State
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [voiceSpeed, setVoiceSpeed] = useState(1);

  const isRTL = story.story_info.language === 'Arabic';
  const currentPage = pages[currentPageIndex];

  // Use aspect ratio from story info, default to 16:9 if missing
  const aspectRatio: AspectRatio = (story.story_info.aspect_ratio as AspectRatio) || '16:9';
  const isVertical = aspectRatio === '9:16';

  // Check if all images are generated
  const allImagesReady = pages.every(p => p.generatedImage);

  const getArtStyleDescription = (style: string) => {
    if (style === 'Photorealistic Human Style') {
      return 'Photorealistic Human Style (Ultra realistic lighting, skin texture, natural facial expressions)';
    }
    return style;
  };

  // Stop speech when page changes
  useEffect(() => {
    window.speechSynthesis.cancel();
    setIsSpeaking(false);
  }, [currentPageIndex]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      window.speechSynthesis.cancel();
    };
  }, []);

  // Auto-generate image for the current page if missing
  useEffect(() => {
    const generateForPage = async () => {
      if (!currentPage.generatedImage && !currentPage.isGeneratingImage) {

        // Mark as generating
        setPages(prev => prev.map((p, idx) => 
          idx === currentPageIndex ? { ...p, isGeneratingImage: true } : p
        ));

        try {
          // Construct a full prompt using character info for consistency
          const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
          ).join(' ');

          const fullPrompt = `Art Style: ${getArtStyleDescription(story.story_info.art_style)}. ${characterContext} Scene: ${currentPage.image_prompt}`;

          const base64Image = await generateIllustration(fullPrompt, aspectRatio);

          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
          ));

        } catch (error) {
          console.error("Failed to generate image", error);
          setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
          ));
        }
      }
    };

    generateForPage();
  }, [currentPageIndex, currentPage.generatedImage, currentPage.isGeneratingImage, currentPage.image_prompt, story.characters, story.story_info.art_style, aspectRatio]);

  const handleNext = () => {
    if (currentPageIndex < pages.length - 1) {
      setCurrentPageIndex(prev => prev + 1);
    }
  };

  const handlePrev = () => {
    if (currentPageIndex > 0) {
      setCurrentPageIndex(prev => prev - 1);
    }
  };

  const handleRegenerateImage = async () => {
    if (isGeneratingImage) return;
    setIsGeneratingImage(true);

    // Clear current image and mark generating
    setPages(prev => prev.map((p, idx) => 
        idx === currentPageIndex ? { ...p, generatedImage: undefined, isGeneratingImage: true } : p
    ));

    try {
        // Step 1: Rewrite prompt
        const newPrompt = await regeneratePrompt(currentPage.image_prompt);

        // Update prompt in state
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, image_prompt: newPrompt } : p
        ));

        // Step 2: Generate new image
        const characterContext = story.characters.map(c => 
            `${c.name} is a ${c.age} year old ${c.gender || 'character'}. Appearance: ${c.description}.`
        ).join(' ');
        const fullPrompt = `Art Style: ${getArtStyleDescription(story.story_info.art_style)}. ${characterContext} Scene: ${newPrompt}`;

        const base64Image = await generateIllustration(fullPrompt, aspectRatio);

        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, generatedImage: base64Image, isGeneratingImage: false } : p
        ));

    } catch (e) {
        console.error("Regeneration failed", e);
        setPages(prev => prev.map((p, idx) => 
            idx === currentPageIndex ? { ...p, isGeneratingImage: false } : p
        ));
    } finally {
        setIsGeneratingImage(false);
    }
  };

  const handleSaveJSON = () => {
    const cleanPages = pages.map(({ isGeneratingImage, ...rest }) => rest);

    const storyData = {
      ...story,
      pages: cleanPages,
      savedAt: new Date().toISOString()
    };

    try {
      localStorage.setItem("sawan_story", JSON.stringify(storyData));
      alert(isRTL ? "✅ تم حفظ القصة بنجاح!" : "✅ Story saved successfully!");
    } catch (e) {
      console.warn("LocalStorage quota exceeded or error, falling back to download", e);

      const jsonString = JSON.stringify(storyData, null, 2);
      const blob = new Blob([jsonString], { type: "application/json" });
      saveAs(blob, `${story.story_info.title.replace(/\s+/g, "_") || "story"}.json`);

      alert(isRTL ? "القصة كبيرة جداً للحفظ في المتصفح. تم تنزيلها كملف بدلاً من ذلك." : "Story is too large for browser storage. Downloaded as file instead.");
    }
    setShowExportMenu(false);
  };

  const handleDownloadPDF = () => {
    try {
        // A4 size: 210 x 297 mm
        const doc = new jsPDF({
            orientation: isVertical ? 'portrait' : 'landscape',
            unit: 'mm',
            format: 'a4'
        });

        // Cover Page
        doc.setFontSize(24);

        // Simple RTL fix for Title if needed, though title is usually short
        let titleText = story.story_info.title;
        if (isRTL) {
             titleText = titleText.split("").reverse().join("");
        }

        doc.text(titleText, 105, 100, { align: 'center' });
        doc.setFontSize(16);
        doc.text(`A story for ${story.story_info.age_group} year olds`, 105, 120, { align: 'center' });

        pages.forEach((page, index) => {
            doc.addPage();

            const pageWidth = doc.internal.pageSize.getWidth();
            const pageHeight = doc.internal.pageSize.getHeight();
            let y = 20;

            // Image
            if (page.generatedImage) {
                // Keep aspect ratio
                const imgData = `data:image/jpeg;base64,${page.generatedImage}`;

                let imgWidth, imgHeight, x;

                if (isVertical) {
                   // Portrait layout
                   imgWidth = pageWidth - 40; // 20mm margins
                   imgHeight = imgWidth * (16/9); 
                   x = 20;
                   y = 20;
                   // Ensure it fits
                   if (imgHeight > pageHeight * 0.6) {
                       imgHeight = pageHeight * 0.6;
                       imgWidth = imgHeight * (9/16);
                       x = (pageWidth - imgWidth) / 2;
                   }
                } else {
                   // Landscape layout
                   imgHeight = pageHeight * 0.6;
                   imgWidth = imgHeight * (16/9);
                   x = (pageWidth - imgWidth) / 2;
                   y = 20;
                }

                try {
                    doc.addImage(imgData, 'JPEG', x, y, imgWidth, imgHeight);
                } catch (err) {
                    console.error("Error adding image to PDF", err);
                }

                // Text
                doc.setFontSize(14);
                // Split text to fit width
                const textWidth = 170; // mm

                let textContent = page.text;
                // RTL manual fix as requested
                if (isRTL) {
                    textContent = textContent.split("").reverse().join("");
                }

                const splitText = doc.splitTextToSize(textContent, textWidth);

                let textY = y + imgHeight + 20;
                // Check if text fits
                if (textY + (splitText.length * 7) > pageHeight) {
                    doc.addPage();
                    textY = 20;
                }

                doc.text(splitText, pageWidth / 2, textY, { align: 'center' });
            } else {
                doc.setFontSize(14);
                let textContent = page.text;
                if (isRTL) {
                    textContent = textContent.split("").reverse().join("");
                }
                const splitText = doc.splitTextToSize(textContent, 170);
                doc.text(splitText, 105, 50, { align: 'center' });
            }

            // Page Number
            doc.setFontSize(10);
            doc.text(`${index + 1}`, 200, 287, { align: 'right' });
        });

        doc.save(`${story.story_info.title || "story"}.pdf`);
    } catch (e) {
        console.error("PDF Export failed", e);
        alert("Could not generate PDF. Please ensure all images are loaded.");
    }
    setShowExportMenu(false);
  };

  const handleDownloadImages = async () => {
    const zip = new JSZip();
    const folder = zip.folder("story-images");

    let count = 0;
    pages.forEach((page, i) => {
        if (page.generatedImage) {
            folder?.file(`page-${i + 1}.jpg`, page.generatedImage, { base64: true });
            count++;
        }
    });

    if (count === 0) {
