                },
                storyText: {
                    fontSize: 16,
                    lineHeight: 1.5,
                    font: isRTL ? 'Amiri' : 'Roboto'
                }
            }
        };

        pdfMake.createPdf(docDefinition).download(`${story.story_info.title || "story"}.pdf`);

    } catch (e) {
        console.error("PDF Export failed", e);
