                            disabled={currentPage.isGeneratingImage}
                            className="bg-black/50 hover:bg-black/70 backdrop-blur-sm p-2 rounded-full text-white transition-all border border-white/10"
                            title="Regenerate Image"
                        >
                            <RefreshCw className={`w-5 h-5 ${currentPage.isGeneratingImage ? 'animate-spin' : ''}`} />
