                    >
                        {isExportingPdf ? <RefreshCw className="w-5 h-5 animate-spin" /> : <FileText className="w-5 h-5" />}
                        {isRTL ? (isExportingPdf ? "جاري التجهيز..." : "تنزيل PDF") : (isExportingPdf ? "Generating..." : "Download PDF")}
                    </button>

