      <footer className="p-6 border-t border-slate-800 bg-[#0f172a] flex items-center justify-between z-20">
        <button 
            onClick={handlePrev} 
            disabled={currentPageIndex === 0}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === 0 
                ? 'text-slate-700 cursor-not-allowed' 
                : 'bg-slate-800 text-slate-300 hover:bg-slate-700 hover:text-white border border-slate-700'
            }`}
        >
            {isRTL ? <ArrowRight className="w-5 h-5 ms-2" /> : <ArrowLeft className="w-5 h-5 me-2" />}
            {isRTL ? "السابق" : "Previous"}
        </button>

        <div className="hidden md:flex gap-2">
            {pages.map((_, idx) => (
                <div 
                    key={idx}
                    className={`w-2.5 h-2.5 rounded-full transition-all ${
                        idx === currentPageIndex ? 'bg-brand-500 scale-125' : 'bg-slate-700'
                    }`}
                />
            ))}
        </div>
        <div className="md:hidden text-slate-500 font-bold">
            {currentPageIndex + 1} / {pages.length}
        </div>

        <button 
            onClick={handleNext} 
            disabled={currentPageIndex === pages.length - 1}
            className={`flex items-center px-6 py-3 rounded-xl font-bold font-heading transition-all ${
                currentPageIndex === pages.length - 1 
                ? 'text-slate-700 cursor-not-allowed' 
                : 'bg-brand-600 text-white hover:bg-brand-500 shadow-lg shadow-brand-900/20'
            }`}
        >
            {isRTL ? "التالي" : "Next"}
            {isRTL ? <ArrowLeft className="w-5 h-5 me-2" /> : <ArrowRight className="w-5 h-5 ms-2" />}
        </button>
      </footer>
    </div>
  );
};

export default StoryBook;

export type Language = 'English' | 'Arabic';
export type AgeGroup = '3-4' | '4-6' | '7-9' | '9-12';
export type AspectRatio = '9:16' | '16:9';
export type ArtStyle = 'Cute Cartoon' | 'Storybook Watercolor' | 'Pixar-like 3D' | 'Soft Pastel Illustration';

export interface StoryParams {
  idea: string;
  language: Language;
  dialect?: string; // Specific dialect for the story
  ageGroup: AgeGroup;
  pageCount: number;
  aspectRatio: AspectRatio;
  artStyle: ArtStyle;
}

export interface Character {
  name: string;
  description: string;
  personality: string;
  age: string | number;
  gender: string;
}

export interface StoryPage {
  page: number;
  text: string;
  image_prompt: string;
  generatedImage?: string; // base64 data
  isGeneratingImage?: boolean;
}

export interface StoryData {
  story_info: {
    title: string;
    language: string;
    age_group: string;
    art_style: string;
    // We inject aspect_ratio manually in the service layer because strict JSON output from AI doesn't include it
    aspect_ratio: AspectRatio; 
  };
  characters: Character[];
  pages: StoryPage[];
}

export interface StoryState {
  step: 'setup' | 'generating_story' | 'reading';
  params: StoryParams;
  data: StoryData | null;
  error: string | null;
}

