                        className="w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-700 text-left rtl:text-right text-slate-200 transition-colors border-t border-slate-700"
                    >
                        {isExportingPdf ? <RefreshCw className="w-4 h-4 text-red-400 animate-spin" /> : <FileText className="w-4 h-4 text-red-400" />}
                        <span>{isRTL ? (isExportingPdf ? "جاري التجهيز..." : "تنزيل PDF") : (isExportingPdf ? "Generating..." : "Download PDF")}</span>
                    </button>
                    <button onClick={handleDownloadImages} className="w-full flex items-center gap-3 px-4 py-3 hover:bg-slate-700 text-left rtl:text-right text-slate-200 transition-colors border-t border-slate-700">
                        <Images className="w-4 h-4 text-blue-400" />
                        <span>{isRTL ? "تنزيل الصور" : "Download Images (ZIP)"}</span>
                    </button>
