            <div className="flex flex-col items-center justify-center gap-4">

                <p className={`text-sm font-bold flex items-center gap-2 ${allImagesReady ? 'text-green-400' : 'text-slate-400'}`} id="storyNotice">
                   {allImagesReady ? (
                       <>
                           <CheckCircle className="w-4 h-4" />
