                                         params.dialect === d.id
                                         ? 'bg-[#22c55e] text-black shadow-md'
                                         : 'bg-[#1e293b] text-slate-300 hover:bg-slate-800'
                                     } ${isLoading ? 'opacity-60 cursor-not-allowed' : ''}`}
