                                        <Lock className="w-3.5 h-3.5" />
                                        <span>LIVE ONLY</span>
                                     </div>
                                </div>
                            )}

                            {/* Image Area */}
                            <div className={`h-44 w-full bg-slate-200 relative ${isLocked ? 'filter blur-[3px]' : ''}`}>
                                <img 
                                    src={style.img} 
                                    alt={style.label}
                                    className="w-full h-full object-cover transition-transform duration-500 hover:scale-110" 
                                    loading="lazy"
                                />
                                {/* Badge */}
                                <div className={`absolute top-3 left-3 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider shadow-sm backdrop-blur-md ${
                                    style.isReal ? 'bg-red-500 text-white' : 'bg-white/90 text-slate-800'
                                }`}>
                                    {style.isReal ? 'Real' : style.badge}
                                </div>
                            </div>

                            {/* Content Area */}
                            <div className={`flex-1 p-4 flex flex-col justify-between bg-white dark:bg-slate-800 ${isLocked ? 'opacity-60' : ''}`}>
                                <div className="font-heading font-bold text-slate-700 dark:text-slate-200 text-center leading-tight">
                                    {style.label}
                                </div>

                                <div className="flex justify-center mt-2">
                                    <div className={`
                                        w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors
                                        ${params.artStyle === style.label ? 'border-purple-500' : 'border-slate-300 dark:border-slate-600'}
                                    `}>
                                        {params.artStyle === style.label && (
                                            <div className="w-3 h-3 bg-purple-500 rounded-full" />
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>
                    )})}
                </div>
            </div>
        </div>

        {/* Action Button or Generation Box */}
        <div className="pt-4">
            {!isLoading ? (
                <button
                    onClick={onSubmit}
                    disabled={!params.idea.trim()}
                    className={`w-full py-6 rounded-2xl text-2xl font-heading font-bold text-white shadow-xl transition-all transform hover:-translate-y-1 ${
                        !params.idea.trim()
                        ? 'bg-gray-300 dark:bg-slate-700 cursor-not-allowed'
                        : 'bg-gradient-to-r from-brand-500 to-brand-600 hover:shadow-2xl hover:scale-[1.01]'
                    }`}
                >
                    {txt.createBtn}
                </button>
            ) : (
                <div className="w-full bg-slate-900 rounded-2xl p-6 shadow-xl border border-slate-700">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-white font-bold font-heading">{txt.generatingTitle}</span>
                        <span className="text-brand-300 font-mono font-bold">{progress}%</span>
                    </div>

                    {/* Progress Bar Container */}
                    <div className="w-full h-3 bg-slate-800 rounded-full overflow-hidden mb-3 border border-slate-700">
                        <div 
                            style={{ width: `${progress}%` }} 
                            className="h-full bg-gradient-to-r from-sky-400 to-indigo-500 transition-all duration-300 ease-out"
                        />
                    </div>

                    <p className="text-slate-400 text-sm mb-4 animate-pulse">{progressMessage}</p>

                    {/* Controls */}
                    <div className="flex justify-center gap-4">
                        {isPaused ? (
                            <button 
                                onClick={onResume}
                                className="flex items-center gap-2 px-6 py-2 bg-green-600 hover:bg-green-500 text-white rounded-lg font-bold transition-colors"
                            >
                                <Play className="w-4 h-4" fill="currentColor" />
                                {txt.resume}
                            </button>
                        ) : (
                            <button 
                                onClick={onPause}
                                className="flex items-center gap-2 px-6 py-2 bg-slate-700 hover:bg-slate-600 text-white rounded-lg font-bold transition-colors"
                            >
                                <Pause className="w-4 h-4" fill="currentColor" />
                                {txt.pause}
                            </button>
                        )}
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default SetupForm;

