import React, { useState } from 'react';
import { BookOpen, Sparkles, Languages, Palette, Settings, Users, FolderOpen, Play, Pause } from 'lucide-react';
import { StoryParams } from '../types';
import { AGE_OPTIONS, ART_STYLE_OPTIONS, ARABIC_DIALECTS } from '../constants';

interface SetupFormProps {
  params: StoryParams;
  onChange: (newParams: StoryParams) => void;
  onSubmit: () => void;
  onLoadStory: () => void;
  isLoading: boolean;
  progress: number;
  progressMessage: string;
  isPaused: boolean;
  onPause: () => void;
  onResume: () => void;
}

const SetupForm: React.FC<SetupFormProps> = ({ 
  params, onChange, onSubmit, onLoadStory, isLoading, 
  progress, progressMessage, isPaused, onPause, onResume 
}) => {
  const handleChange = <K extends keyof StoryParams>(key: K, value: StoryParams[K]) => {
    onChange({ ...params, [key]: value });
  };

  const handleSliderChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    handleChange('pageCount', parseInt(e.target.value));
  };

  const handleLanguageChange = (lang: 'English' | 'Arabic') => {
    if (isLoading) return;
    onChange({
        ...params,
        language: lang,
        dialect: lang === 'English' ? 'Standard American English' : 'Egyptian Arabic' // Default dialect
    });
  };

  const handleDialectChange = (dialect: string) => {
    if (isLoading) return;
    handleChange('dialect', dialect);
  };

  const t = {
    English: {
      storyAbout: "What is your story about?",
      storyPlaceholder: "e.g., A brave little rabbit who wants to fly to the moon...",
      ageGroup: "Age Group",
      language: "Language",
      storySettings: "Story Settings",
      artStyle: "Art Style",
      createBtn: "Create My Story!",
      loadStory: "Load Story",
      generatingTitle: "Weaving your story...",
      pause: "Pause",
      resume: "Resume",
      settingsTitle: "📖 Story Settings",
      short: "Short (6)",
