            content.push({
                text: `${index + 1}`,
                alignment: 'center',
                margin: [0, 20, 0, 0],
                fontSize: 10,
                color: '#666',
                pageBreak: index === pages.length - 1 ? undefined : 'after'
            });
        });

        // Define Styles
        const docDefinition = {
            pageSize: 'A4',
            pageMargins: [40, 40, 40, 40],
            content: content,
            defaultStyle: {
                font: isRTL ? 'Amiri' : 'Roboto',
                direction: isRTL ? 'rtl' : 'ltr'
