                            borderColor: style.color,
                            boxShadow: `0 0 0 2px ${style.color}33`,
                            backgroundColor: `${style.color}10`
                        } : {}}
                        className={`
                            cursor-pointer p-4 rounded-xl border-2 transition-all flex items-center justify-between gap-2 min-h-[60px]
