interface SetupFormProps {
  params: StoryParams;
  onChange: (newParams: StoryParams) => void;
  onSubmit: () => void;
  onLoadStory: () => void;
  isLoading: boolean;
  progress: number;
  progressMessage: string;
  isPaused: boolean;
  onPause: () => void;
  onResume: () => void;
}

