  const handleLanguageChange = (lang: 'English' | 'Arabic') => {
    if (isLoading) return;
    onChange({
        ...params,
        language: lang,
        dialect: lang === 'English' ? 'Standard American English' : 'Standard Arabic' // Default dialect
