      resume: "Resume",
      settingsTitle: "📖 Story Settings",
      short: "Short (6)",
      fun: "Medium (12)",
      scenesLabel: "🎬 Number of Scenes",
      sceneUnit: "Scene",
      mobile: "📱 Mobile",
