           backgroundImage: `linear-gradient(rgba(0,0,0,0.45), rgba(0,0,0,0.45)), url('https://images.unsplash.com/photo-1516627987034-1b45b4b1d3f1?auto=format&fit=crop&w=1600&q=80')`,
           backgroundSize: 'cover',
           backgroundPosition: 'center 65%',
           backgroundRepeat: 'no-repeat',
           minHeight: '260px'
        }}
      >
        {/* Load Story Button */}
        <div className="absolute top-6 right-6 z-20 rtl:left-6 rtl:right-auto">
            <button 
                id="loadStory"
                onClick={onLoadStory}
                disabled={isLoading}
