            >
                <FolderOpen className="w-5 h-5" />
                <span className="hidden sm:inline">{txt.loadStory}</span>
            </button>
        </div>

        <div className="relative z-10">
            <div className="inline-flex items-center justify-center p-3 card rounded-full shadow-lg mb-4">
