            dir="auto"
            disabled={isLoading}
            className="w-full p-4 border-2 border-brand-100 dark:border-slate-700 rounded-2xl focus:border-brand-400 dark:focus:border-brand-400 focus:ring-4 focus:ring-brand-100 dark:focus:ring-brand-900 transition-all outline-none resize-none h-32 text-gray-700 dark:text-gray-200 card text-lg placeholder-gray-400 dark:placeholder-gray-500 disabled:opacity-70 disabled:cursor-not-allowed"
          />
        </div>

        {/* Age Group */}
        <div className="space-y-4">
          <label className="flex items-center text-gray-700 dark:text-gray-200 font-bold font-heading text-xl">
            <Users className="w-6 h-6 me-2 text-purple-500" />
