    onChange({
        ...params,
        language: lang,
        dialect: lang === 'English' ? 'Standard American English' : 'Standard Arabic' // Default dialect
    });
  };

  const handleDialectChange = (dialect: string) => {
    if (isLoading) return;
    handleChange('dialect', dialect);
  };

