                        type="range" 
                        min="1" 
                        max="3000"
                        value={params.pageCount}
                        onChange={handleSliderChange}
                        disabled={isLoading}
                        className="w-full h-1.5 bg-white/30 rounded-lg appearance-none cursor-pointer accent-yellow-400"
                    />
