           backgroundSize: 'cover',
           backgroundPosition: 'center 65%',
           backgroundRepeat: 'no-repeat',
           minHeight: '260px'
        }}
      >
        {/* Load Story Button */}
        <div className="absolute top-6 right-6 z-20 rtl:left-6 rtl:right-auto">
            <button 
