import React, { useState } from 'react';

interface GameProps {
  language: 'English' | 'Arabic';
}

export const GeneratorMotorGame: React.FC<GameProps> = ({ language }) => {
  const [genSelection, setGenSelection] = useState<string[]>([]);
  const [motorSelection, setMotorSelection] = useState<string[]>([]);
  const [result, setResult] = useState<'success' | 'error' | null>(null);

  const isAr = language === 'Arabic';

  const items = {
    coil: { en: "Coil", ar: "ملف" },
    magnet: { en: "Permanent Magnet", ar: "مغناطيس دائم" },
    electricSource: { en: "Electric Source", ar: "مصدر كهربائي" },
    kineticSource: { en: "Kinetic Energy Source", ar: "مصدر طاقة حركية" },
    electricOutput: { en: "Electric Energy Output", ar: "مخرج طاقة كهربائية" },
  };

  // Correct answers
  const genCorrect = ["coil", "magnet", "kineticSource", "electricOutput"];
  const motorCorrect = ["coil", "magnet", "electricSource"];

  // Wrong answers (must not be selected)
  const genWrong = ["electricSource"];
  const motorWrong = ["kineticSource", "electricOutput"];

  const toggleSelection = (key: string, list: string[], setList: React.Dispatch<React.SetStateAction<string[]>>) => {
    if (list.includes(key)) {
      setList(list.filter(k => k !== key));
    } else {
      setList([...list, key]);
    }
    setResult(null);
  };

  const checkAnswer = () => {
    // Generator Logic: Must have all correct items AND no wrong items
    const genHasAllCorrect = genCorrect.every(k => genSelection.includes(k));
    const genHasNoWrong = !genSelection.some(k => genWrong.includes(k));

    // Motor Logic: Must have all correct items AND no wrong items
    const motorHasAllCorrect = motorCorrect.every(k => motorSelection.includes(k));
    const motorHasNoWrong = !motorSelection.some(k => motorWrong.includes(k));

    if (genHasAllCorrect && genHasNoWrong && motorHasAllCorrect && motorHasNoWrong) {
      setResult('success');
    } else {
      setResult('error');
    }
  };

  const t = {
    title: isAr ? "لعبة: المولد vs المحرك" : "Game: Generator vs Motor",
    desc: isAr ? "اختر الأجزاء الصحيحة بناءً على اتجاه الطاقة" : "Select correct parts based on energy flow",
    genTitle: isAr ? "المولد الكهربائي 🔵" : "Electric Generator 🔵",
    genDesc: isAr ? "يحول طاقة حركية -> كهربائية" : "Kinetic -> Electrical Energy",
    motorTitle: isAr ? "المحرك الكهربائي 🔴" : "Electric Motor 🔴",
    motorDesc: isAr ? "يحول طاقة كهربائية -> حركية" : "Electrical -> Kinetic Energy",
    check: isAr ? "تحقق من الإجابة" : "Check Answer",
    success: isAr ? "✅ أحسنت! فهمت الفرق بين المولد والمحرك." : "✅ Well done! You understand the difference.",
    error: isAr ? "❌ حاول مرة أخرى. راجع اتجاه الطاقة." : "❌ Try again. Check the energy flow direction.",
  };

  return (
    <div className="w-full text-left rtl:text-right">
      <h3 className="text-xl font-bold mb-2 text-yellow-400 text-center">{t.title}</h3>
      <p className="text-slate-400 text-sm mb-4 text-center">{t.desc}</p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        {/* Generator */}
        <div className="border border-slate-600 rounded-xl p-3 bg-slate-800/50">
          <h4 className="font-bold text-sky-400 mb-1">{t.genTitle}</h4>
          <p className="text-[11px] text-slate-400 mb-3 font-mono">{t.genDesc}</p>
          <div className="space-y-2">
            {Object.entries(items).map(([key, label]) => (
              <label key={`gen-${key}`} className="flex items-center gap-2 cursor-pointer p-1.5 hover:bg-white/5 rounded transition-colors select-none">
                <input 
                  type="checkbox" 
                  checked={genSelection.includes(key)}
                  onChange={() => toggleSelection(key, genSelection, setGenSelection)}
                  className="w-4 h-4 rounded border-slate-500 bg-slate-700 text-sky-500 focus:ring-sky-500"
                />
                <span className="text-xs font-bold text-slate-300">{isAr ? label.ar : label.en}</span>
              </label>
            ))}
          </div>
        </div>

        {/* Motor */}
        <div className="border border-slate-600 rounded-xl p-3 bg-slate-800/50">
          <h4 className="font-bold text-red-400 mb-1">{t.motorTitle}</h4>
          <p className="text-[11px] text-slate-400 mb-3 font-mono">{t.motorDesc}</p>
          <div className="space-y-2">
            {Object.entries(items).map(([key, label]) => (
              <label key={`motor-${key}`} className="flex items-center gap-2 cursor-pointer p-1.5 hover:bg-white/5 rounded transition-colors select-none">
                <input 
                  type="checkbox" 
                  checked={motorSelection.includes(key)}
                  onChange={() => toggleSelection(key, motorSelection, setMotorSelection)}
                  className="w-4 h-4 rounded border-slate-500 bg-slate-700 text-red-500 focus:ring-red-500"
                />
                <span className="text-xs font-bold text-slate-300">{isAr ? label.ar : label.en}</span>
              </label>
            ))}
          </div>
        </div>
      </div>

      <div className="flex flex-col items-center gap-3">
        <button 
          onClick={checkAnswer}
          className="w-full md:w-auto px-8 py-3 bg-slate-100 text-slate-900 rounded-xl font-bold hover:bg-white transition-all shadow-lg hover:scale-105 active:scale-95"
        >
          {t.check}
        </button>

        {result && (
          <div className={`text-sm font-bold px-4 py-2 rounded-lg animate-bounce ${result === 'success' ? 'bg-green-500/20 text-green-400 border border-green-500/30' : 'bg-red-500/20 text-red-400 border border-red-500/30'}`}>
            {result === 'success' ? t.success : t.error}
          </div>
        )}
      </div>
    </div>
  );
};

