import React, { useState, useEffect, useRef } from 'react';
import { StoryParams, StoryState } from './types';
import { INITIAL_STORY_PARAMS } from './constants';
import { StoryGenerator } from './services/gemini';
import SetupForm from './components/SetupForm';
import StoryBook from './components/StoryBook';
import { GamesDashboard } from './components/GamesDashboard';
import { Gamepad2 } from 'lucide-react';

// Apply Language Helper - Defined outside to run immediately
const applyLanguage = (langCode: string) => {
  const html = document.documentElement;

  // Persist choice
  localStorage.setItem("uiLang", langCode);

  if (langCode === "ar") {
    html.setAttribute("lang", "ar");
    html.setAttribute("dir", "rtl");
    html.classList.add("rtl");
  } else {
    html.setAttribute("lang", "en");
    html.setAttribute("dir", "ltr");
    html.classList.remove("rtl");
  }
};

// Run immediately to set initial document state before React renders
const savedUiLang = localStorage.getItem("uiLang") || "en";
applyLanguage(savedUiLang);

const App: React.FC = () => {
  const [state, setState] = useState<StoryState>({
    step: 'setup',
    params: {
      ...INITIAL_STORY_PARAMS,
      // Initialize state language based on persisted value to match DOM
      language: (localStorage.getItem("uiLang") === 'ar' ? 'Arabic' : 'English')
    },
    data: null,
    error: null,
  });

  const [isLoading, setIsLoading] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // View State (Story vs Games)
  const [showGames, setShowGames] = useState(false);

  // Generation Control State
  const [progress, setProgress] = useState(0);
  const [progressMessage, setProgressMessage] = useState("Starting...");
  const [isPaused, setIsPaused] = useState(false);

  // Use a ref for the generator so it persists across renders
  const generatorRef = useRef<StoryGenerator>(new StoryGenerator());

  // Initialize theme on mount
  useEffect(() => {
    const savedTheme = localStorage.getItem("theme");
    if (savedTheme) {
      document.documentElement.setAttribute("data-theme", savedTheme);
      setIsDarkMode(savedTheme === 'dark');
    } else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      document.documentElement.setAttribute("data-theme", 'dark');
      setIsDarkMode(true);
    }
  }, []);

  // Sync Language with DOM when state changes
  useEffect(() => {
    const lang = state.params.language;
    const langCode = lang === 'Arabic' ? 'ar' : 'en';
    applyLanguage(langCode);
  }, [state.params.language]);

  // Global click listener for empty links (Universal Share Fix requirement)
  useEffect(() => {
    const handleLinkClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const a = target.closest("a");
      if(a){
        const href = a.getAttribute("href");
        // Prevent default if href is missing, empty, or just a hash
        if(!href || href === "#" || href === ""){
          e.preventDefault();
        }
      }
    };
    document.addEventListener("click", handleLinkClick);
    return () => document.removeEventListener("click", handleLinkClick);
  }, []);

  const toggleTheme = () => {
    const newTheme = isDarkMode ? 'light' : 'dark';
    document.documentElement.setAttribute("data-theme", newTheme);
    localStorage.setItem("theme", newTheme);
    setIsDarkMode(!isDarkMode);
  };

  const toggleLanguage = () => {
    const currentLang = state.params.language;
    const newLang = currentLang === 'English' ? 'Arabic' : 'English';

    setState(prev => ({
        ...prev,
        params: { ...prev.params, language: newLang }
    }));
  };

  const handleParamsChange = (newParams: StoryParams) => {
    setState(prev => ({ ...prev, params: newParams }));
  };

  const handleCreateStory = async () => {
    setIsLoading(true);
    setState(prev => ({ ...prev, error: null }));
    setProgress(0);
    setProgressMessage(state.params.language === 'Arabic' ? "جاري التحضير..." : "Preparing...");
    setIsPaused(false);

    // Ensure generator is reset/ready
    generatorRef.current.resume();

    try {
      const storyData = await generatorRef.current.generate(
        state.params, 
        (prog, msg) => {
          setProgress(prog);
          setProgressMessage(msg);
        }
      );

      setState(prev => ({
        ...prev,
        step: 'reading',
        data: storyData
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({
        ...prev,
        error: "Oops! We couldn't create the story right now. Please try again."
      }));
    } finally {
      setIsLoading(false);
    }
  };

  const handlePause = () => {
    setIsPaused(true);
    generatorRef.current.pause();
  };

  const handleResume = () => {
    setIsPaused(false);
    generatorRef.current.resume();
  };

  const handleLoadStory = () => {
    const savedData = localStorage.getItem("sawan_story");
    const isArabic = state.params.language === 'Arabic';

    const loadFromFile = () => {
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = 'application/json';
      input.onchange = (e) => {
        const file = (e.target as HTMLInputElement).files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
          try {
            const json = JSON.parse(event.target?.result as string);
            // Basic validation to ensure it looks like a story
            if (json.story_info && json.pages) {
                setState(prev => ({
                    ...prev,
                    step: 'reading',
                    data: json
                }));
            } else {
                throw new Error("Invalid story format");
            }
          } catch (err) {
            alert(isArabic ? "ملف غير صالح." : "Invalid story file.");
          }
        };
        reader.readAsText(file);
      };
      input.click();
    };

    if (savedData) {
      const message = isArabic 
        ? "وجدنا قصة محفوظة في المتصفح. هل تريد استكمالها؟\n\nاضغط 'موافق' للتحميل.\nاضغط 'إلغاء' لرفع ملف قصة من جهازك."
        : "Found a saved story in browser storage. Do you want to load it?\n\nClick 'OK' to load saved story.\nClick 'Cancel' to upload a file from your device.";

      if (window.confirm(message)) {
        try {
          const story = JSON.parse(savedData);
          setState(prev => ({
            ...prev,
            step: 'reading',
            data: story
          }));
        } catch (e) {
           console.error("Failed to load local story", e);
           loadFromFile();
        }
      } else {
        loadFromFile();
      }
    } else {
      loadFromFile();
    }
  };

  const handleReset = () => {
    setState({
      step: 'setup',
      params: {
        ...INITIAL_STORY_PARAMS,
        // Preserve current language selection on reset
        language: state.params.language
      },
      data: null,
      error: null
    });
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      {/* Global Header Controls */}
      <div className="top-actions">
        {/* Games Toggle Button */}
        <button
            onClick={() => setShowGames(!showGames)}
            className="flex items-center gap-2 bg-amber-500 hover:bg-amber-400 text-slate-900 font-extrabold px-4 py-2 rounded-2xl transition-all shadow-lg hover:shadow-amber-500/20 hover:scale-105 active:scale-95"
            title={state.params.language === 'English' ? 'Educational Games' : 'الألعاب التعليمية'}
        >
            <Gamepad2 className="w-5 h-5" />
            <span className="hidden sm:inline">{state.params.language === 'English' ? 'Games' : 'ألعاب'}</span>
        </button>

        <button 
          id="themeToggle" 
          type="button"
          onClick={toggleTheme} 
          title={isDarkMode ? "Light Mode" : "Dark Mode"}
        >
          {isDarkMode ? '☀️' : '🌙'}
        </button>

        <button 
          id="langToggle" 
          type="button"
          onClick={toggleLanguage}
          title={state.params.language === 'English' ? "العربية" : "English"}
        >
          {/* Flag represents the TARGET language to switch to, or current status indicator */}
          <img 
            src={state.params.language === 'English' ? "https://flagcdn.com/w40/eg.png" : "https://flagcdn.com/w40/us.png"} 
            alt={state.params.language === 'English' ? "Arabic" : "English"} 
          />
        </button>
      </div>

      {showGames ? (
          <GamesDashboard 
            language={state.params.language} 
            onBack={() => setShowGames(false)} 
          />
      ) : (
          <>
            {state.step === 'setup' && (
                <div className="flex-1 flex flex-col items-center justify-center p-4">
                <SetupForm 
                    params={state.params} 
                    onChange={handleParamsChange} 
                    onSubmit={handleCreateStory}
                    onLoadStory={handleLoadStory}
                    isLoading={isLoading}
                    progress={progress}
                    progressMessage={progressMessage}
                    isPaused={isPaused}
                    onPause={handlePause}
                    onResume={handleResume}
                />
                {state.error && (
                    <div className="mt-4 p-4 bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 rounded-xl border border-red-200 dark:border-red-800">
                    {state.error}
                    </div>
                )}
                </div>
            )}

            {state.step === 'reading' && state.data && (
                <StoryBook story={state.data} onReset={handleReset} />
            )}
          </>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface GameProps {
  language: 'English' | 'Arabic';
}

export const GeneratorMotorGame: React.FC<GameProps> = ({ language }) => {
  const [genSelection, setGenSelection] = useState<string[]>([]);
  const [motorSelection, setMotorSelection] = useState<string[]>([]);
  const [result, setResult] = useState<'success' | 'error' | null>(null);

  const isAr = language === 'Arabic';

  // Generator Items (Based on user script)
  const genItems = [
    { id: 'coil', en: "Coil (Wire)", ar: "ملف (سلك)" },
    { id: 'magnet', en: "Magnet", ar: "مغناطيس" },
    { id: 'motion', en: "Motion Source", ar: "مصدر حركة" }, // Correct
    { id: 'battery', en: "Battery", ar: "بطارية" } // Wrong for generator (it produces, doesn't need battery)
  ];
  const genCorrect = ['coil', 'magnet', 'motion'];

  // Motor Items (Based on user script)
  const motorItems = [
    { id: 'coil', en: "Coil (Wire)", ar: "ملف (سلك)" },
    { id: 'magnet', en: "Magnet", ar: "مغناطيس" },
    { id: 'battery', en: "Electric Source (Battery)", ar: "مصدر كهرباء (بطارية)" }, // Correct
    { id: 'lamp', en: "Lamp", ar: "مصباح" } // Wrong (Motor creates motion, lamp is just another load)
  ];
  const motorCorrect = ['coil', 'magnet', 'battery'];

  const toggleSelection = (key: string, list: string[], setList: React.Dispatch<React.SetStateAction<string[]>>) => {
    if (list.includes(key)) {
      setList(list.filter(k => k !== key));
    } else {
      setList([...list, key]);
    }
    setResult(null);
  };

  const checkAnswer = () => {
    // Scoring Logic from script: +1 for correct, -1 for wrong selected
    let score = 0;

    // Generator Score
    genSelection.forEach(id => {
        if (genCorrect.includes(id)) score++;
        else score--;
    });

    // Motor Score
    motorSelection.forEach(id => {
        if (motorCorrect.includes(id)) score++;
        else score--;
    });

    // Max potential score = 3 (gen) + 3 (motor) = 6.
    // Script threshold was 5.
    // We can use strict logic or the score logic. Strict is clearer for UI feedback.
    // Let's use strict logic for "Success" state to ensure mastery.

    const genOk = genCorrect.every(i => genSelection.includes(i)) && !genSelection.some(i => !genCorrect.includes(i));
    const motorOk = motorCorrect.every(i => motorSelection.includes(i)) && !motorSelection.some(i => !motorCorrect.includes(i));

    if (genOk && motorOk) {
      setResult('success');
    } else {
      setResult('error');
    }
  };

  const t = {
    title: isAr ? "لعبة: المولد vs المحرك" : "Game: Generator vs Motor",
    desc: isAr ? "اختر الأجزاء الصحيحة لكل جهاز" : "Select the correct parts for each device",
    genTitle: isAr ? "المولد الكهربائي 🔋" : "Electric Generator 🔋",
    motorTitle: isAr ? "المحرك الكهربائي ⚡" : "Electric Motor ⚡",
    check: isAr ? "✔ تحقق" : "✔ Check",
    success: isAr ? "🎉 ممتاز! فهمك ممتاز للطاقة الكهربائية" : "🎉 Excellent! You understand electrical energy well.",
    error: isAr ? "❌ حاول مرة أخرى وفكّر في مصدر الطاقة" : "❌ Try again. Think about the energy source.",
  };

  return (
    <div className="w-full text-left rtl:text-right">
      <h3 className="text-xl font-bold mb-2 text-yellow-400 text-center">{t.title}</h3>
      <p className="text-slate-400 text-sm mb-6 text-center">{t.desc}</p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        {/* Generator Card */}
        <div className="border-2 border-slate-600 rounded-2xl p-5 bg-slate-800/80 shadow-lg hover:border-sky-500/50 transition-colors">
          <h4 className="font-bold text-sky-400 mb-4 text-lg border-b border-white/10 pb-2">{t.genTitle}</h4>
          <div className="space-y-3">
            {genItems.map((item) => (
              <label key={`gen-${item.id}`} className="flex items-center gap-3 cursor-pointer p-2 hover:bg-white/5 rounded-lg transition-colors select-none group">
                <div className={`w-6 h-6 rounded border-2 flex items-center justify-center transition-colors ${genSelection.includes(item.id) ? 'bg-sky-500 border-sky-500' : 'border-slate-500 group-hover:border-sky-400'}`}>
                    {genSelection.includes(item.id) && <span className="text-white font-bold text-sm">✓</span>}
                </div>
                <input 
                  type="checkbox" 
                  className="hidden"
                  checked={genSelection.includes(item.id)}
                  onChange={() => toggleSelection(item.id, genSelection, setGenSelection)}
                />
                <span className="text-base font-bold text-slate-300 group-hover:text-white transition-colors">{isAr ? item.ar : item.en}</span>
              </label>
            ))}
          </div>
        </div>

        {/* Motor Card */}
        <div className="border-2 border-slate-600 rounded-2xl p-5 bg-slate-800/80 shadow-lg hover:border-red-500/50 transition-colors">
          <h4 className="font-bold text-red-400 mb-4 text-lg border-b border-white/10 pb-2">{t.motorTitle}</h4>
          <div className="space-y-3">
            {motorItems.map((item) => (
              <label key={`motor-${item.id}`} className="flex items-center gap-3 cursor-pointer p-2 hover:bg-white/5 rounded-lg transition-colors select-none group">
                <div className={`w-6 h-6 rounded border-2 flex items-center justify-center transition-colors ${motorSelection.includes(item.id) ? 'bg-red-500 border-red-500' : 'border-slate-500 group-hover:border-red-400'}`}>
                     {motorSelection.includes(item.id) && <span className="text-white font-bold text-sm">✓</span>}
                </div>
                <input 
                  type="checkbox" 
                  className="hidden"
                  checked={motorSelection.includes(item.id)}
                  onChange={() => toggleSelection(item.id, motorSelection, setMotorSelection)}
                />
                <span className="text-base font-bold text-slate-300 group-hover:text-white transition-colors">{isAr ? item.ar : item.en}</span>
              </label>
            ))}
          </div>
        </div>
      </div>

      <div className="flex flex-col items-center gap-4">
        <button 
          onClick={checkAnswer}
          className="w-full md:w-auto px-10 py-3 bg-gradient-to-r from-brand-500 to-sky-500 hover:from-brand-400 hover:to-sky-400 text-white rounded-xl font-bold transition-all shadow-lg hover:shadow-sky-500/20 active:scale-95 text-lg"
        >
          {t.check}
        </button>

        {result && (
          <div className={`text-lg font-bold px-6 py-3 rounded-xl animate-bounce shadow-lg border-2 ${result === 'success' ? 'bg-green-500/20 text-green-400 border-green-500/50' : 'bg-red-500/20 text-red-400 border-red-500/50'}`}>
            {result === 'success' ? t.success : t.error}
          </div>
        )}
      </div>
    </div>
  );
};

