export const CandyGame: React.FC<Props> = ({ language }) => {
  const [currentQIndex, setCurrentQIndex] = useState(0);
  const [candies, setCandies] = useState(0);
  const [gameState, setGameState] = useState<'start' | 'playing' | 'feedback'>('start');
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [shuffledAnswers, setShuffledAnswers] = useState<any[]>([]);

  const isAr = language === 'Arabic';
  const t = {
    title: isAr ? "🍬 من سيربح البونبون" : "🍬 Who Will Win the Candy",
    desc: isAr ? "اختبر معلوماتك واربح بونبون أكتر!" : "Test your knowledge and win candies!",
    start: isAr ? "ابدأ اللعبة" : "Start Game",
    next: isAr ? "سؤال جديد" : "Next Question",
    win: isAr ? "مجموع البونبون:" : "Total Candies:",
    correct: isAr ? "إجابة صحيحة! +100 🍬" : "Correct Answer! +100 🍬",
    wrong: isAr ? "إجابة خاطئة 😢" : "Wrong Answer 😢",
    question: isAr ? "السؤال" : "Question"
  };

  const loadQuestion = useCallback(() => {
    // Pick random question
    const randomIndex = Math.floor(Math.random() * QUESTIONS.length);
    setCurrentQIndex(randomIndex);

    // Shuffle answers
    const q = QUESTIONS[randomIndex];
    const answers = [...q.a].sort(() => Math.random() - 0.5);
    setShuffledAnswers(answers);

    setGameState('playing');
    setFeedback(null);
  }, []);

  const handleAnswer = (isCorrect: boolean) => {
    if (gameState !== 'playing') return;

    if (isCorrect) {
      setCandies(c => c + 100);
      setFeedback('correct');
    } else {
      setFeedback('wrong');
    }
    setGameState('feedback');
  };

  return (
    <div className="w-full text-center space-y-8 max-w-2xl mx-auto">
      <div className="mb-4">
        <h3 className="text-3xl font-bold mb-2 text-pink-400 flex items-center justify-center gap-2">
            <Candy className="w-8 h-8" />
            {t.title}
            <Candy className="w-8 h-8" />
        </h3>
        <p className="text-slate-400 text-lg">{t.desc}</p>
      </div>

      <div className="bg-slate-800 p-8 rounded-3xl border-4 border-pink-400/30 shadow-2xl relative overflow-hidden">
        {/* Candy Background Pattern */}
        <div className="absolute inset-0 opacity-5 pointer-events-none" 
             style={{ backgroundImage: 'radial-gradient(circle, #f472b6 2px, transparent 2px)', backgroundSize: '24px 24px' }}>
        </div>

        {/* Score Board */}
        <div className="absolute top-4 right-4 bg-slate-900/80 px-4 py-2 rounded-full border border-yellow-500/50 flex items-center gap-2 rtl:right-auto rtl:left-4">
             <Trophy className="w-4 h-4 text-yellow-400" />
             <span className="text-yellow-400 font-bold">{candies}</span>
        </div>

        {gameState === 'start' && (
            <div className="py-10">
                <Candy className="w-24 h-24 text-pink-500 mx-auto mb-6 animate-bounce" />
                <button 
                    onClick={loadQuestion}
                    className="px-10 py-4 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-400 hover:to-rose-400 text-white text-xl font-bold rounded-2xl shadow-lg transition-transform hover:scale-105"
                >
                    {t.start}
                </button>
            </div>
        )}

        {gameState === 'playing' && (
            <div className="animate-fade-in relative z-10">
                <h4 className="text-slate-400 text-sm font-bold uppercase tracking-widest mb-4">{t.question}</h4>
                <p className="text-2xl md:text-3xl font-bold text-white mb-8 leading-relaxed">
                    {isAr ? QUESTIONS[currentQIndex].q.ar : QUESTIONS[currentQIndex].q.en}
                </p>

                <div className="grid grid-cols-1 gap-3">
                    {shuffledAnswers.map((ans, idx) => (
                        <button
                            key={idx}
                            onClick={() => handleAnswer(ans.c)}
                            className="w-full p-4 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded-xl transition-all border-2 border-transparent hover:border-pink-400 text-lg shadow-md active:scale-95"
                        >
                            {isAr ? ans.t.ar : ans.t.en}
                        </button>
                    ))}
                </div>
            </div>
        )}

        {gameState === 'feedback' && (
            <div className="py-8 animate-fade-in relative z-10">
                {feedback === 'correct' ? (
                    <div className="flex flex-col items-center">
                        <CheckCircle className="w-20 h-20 text-green-400 mb-4" />
                        <h2 className="text-2xl font-bold text-green-400 mb-6">{t.correct}</h2>
                    </div>
                ) : (
                    <div className="flex flex-col items-center">
                        <XCircle className="w-20 h-20 text-red-400 mb-4" />
                        <h2 className="text-2xl font-bold text-red-400 mb-6">{t.wrong}</h2>
                    </div>
                )}

                <button 
                    onClick={loadQuestion}
                    className="px-8 py-3 bg-sky-500 hover:bg-sky-400 text-white font-bold rounded-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center gap-2 mx-auto"
                >
                    {t.next} 
                    {isAr ? <ArrowRight className="w-5 h-5 rotate-180" /> : <ArrowRight className="w-5 h-5" />}
                </button>
            </div>
        )}
      </div>
    </div>
  );
};

