  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [shuffledAnswers, setShuffledAnswers] = useState<any[]>([]);

  // Stable API exposure
  useEffect(() => {
    (window as any).addCandy = (amount: number) => {
        setCandies(prev => prev + amount);
    };

    (window as any).correctAnswer = () => {
        setCandies(current => {
            // Find the next level based on current candies
            let nextVal = LEVELS[0];
            for (let i = 0; i < LEVELS.length; i++) {
                if (current < LEVELS[i]) {
                    nextVal = LEVELS[i];
                    break;
                }
                // If we are at the top or beyond, stay at top
                if (i === LEVELS.length - 1) {
                    nextVal = LEVELS[i];
                }
            }
            return nextVal;
        });
        setFeedback('correct');
        setGameState('feedback');
    };

    (window as any).wrongAnswer = () => {
        setFeedback('wrong');
        setGameState('feedback');
    };

