            }
        }

        setCandies(nextVal);
        setFeedback('correct');
        setGameState('feedback');
    };

    (window as any).wrongAnswer = () => {
        const current = candiesRef.current;

        // Calculate Safe Haven
        let safe = 0;
        for (const level of SAFE_LEVELS) {
