export const CandyGame: React.FC<Props> = ({ language }) => {
  const [levelIndex, setLevelIndex] = useState(0);
  const [safeCandy, setSafeCandy] = useState(0);

  const [currentQIndex, setCurrentQIndex] = useState(0);
  const [gameState, setGameState] = useState<'start' | 'playing' | 'feedback' | 'gameover'>('start');
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);
  const [shuffledAnswers, setShuffledAnswers] = useState<any[]>([]);

  // Mascot State
  const [mascot, setMascot] = useState<{type: 'win'|'lose', text: string} | null>(null);
  const mascotTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Audio
  const candySound = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    candySound.current = new Audio("https://assets.mixkit.co/sfx/preview/mixkit-game-success-alert-2039.mp3");
  }, []);

  const showMascot = (type: 'win' | 'lose') => {
    if (mascotTimeoutRef.current) clearTimeout(mascotTimeoutRef.current);

    const msgs = MESSAGES[type];
    const text = msgs[Math.floor(Math.random() * msgs.length)];

    setMascot({ type, text });

    mascotTimeoutRef.current = setTimeout(() => {
        setMascot(null);
    }, 4000);
  };

  const playWinSound = () => {
    if (candySound.current) {
        candySound.current.currentTime = 0;
        candySound.current.play().catch(e => console.log("Audio play blocked", e));
    }
  };

  // State Refs for window access
  const levelRef = useRef(levelIndex);
  const safeRef = useRef(safeCandy);

  useEffect(() => {
      levelRef.current = levelIndex;
      safeRef.current = safeCandy;
  }, [levelIndex, safeCandy]);

  // Global API Exposure
  useEffect(() => {
    (window as any).correctAnswer = () => {
        const currentLvl = levelRef.current;
        const nextLvl = currentLvl + 1;

        // Update Level
        if (nextLvl < LEVELS.length) {
            setLevelIndex(nextLvl);
            if (SAFE_INDICES.includes(nextLvl)) {
                setSafeCandy(LEVELS[nextLvl]);
            }
        } else {
             // Max level reached (Win Game)
             setLevelIndex(LEVELS.length - 1);
        }

        playWinSound();
        showMascot('win');

        // Advance UI
        setFeedback('correct');
        setGameState('feedback');
    };

    (window as any).wrongAnswer = () => {
        showMascot('lose');
        setFeedback('wrong');
        setGameState('gameover');
    };

    return () => {
        delete (window as any).correctAnswer;
        delete (window as any).wrongAnswer;
    };
  }, []);

  const isAr = language === 'Arabic';
  const t = {
    title: isAr ? "🍬 من سيربح البونبون" : "🍬 Who Will Win the Candy",
    desc: isAr ? "أجب عن الأسئلة واصعد سلم البونبون!" : "Answer questions and climb the Candy Ladder!",
    start: isAr ? "ابدأ اللعبة" : "Start Game",
    next: isAr ? "سؤال جديد" : "Next Question",
    retry: isAr ? "حاول مرة أخرى" : "Try Again",
    correct: isAr ? "إجابة صحيحة! 🎉" : "Correct Answer! 🎉",
    wrong: isAr ? "إجابة خاطئة 😢" : "Wrong Answer 😢",
    gameOver: isAr ? "انتهت اللعبة!" : "Game Over!",
    youWon: isAr ? "لقد ربحت:" : "You won:",
    locked: isAr ? "رصيد مضمون" : "Safe Haven",
    ladder: isAr ? "شجرة البونبون" : "Candy Ladder"
  };

  const loadQuestion = useCallback(() => {
    // Pick random question, try not to repeat immediate previous if possible (simple random for now)
    const randomIndex = Math.floor(Math.random() * QUESTIONS.length);
    setCurrentQIndex(randomIndex);

    const q = QUESTIONS[randomIndex];
    const answers = [...q.a].sort(() => Math.random() - 0.5);
    setShuffledAnswers(answers);

    setGameState('playing');
    setFeedback(null);
  }, []);

  const restartGame = () => {
      setLevelIndex(0);
      setSafeCandy(0);
      loadQuestion();
  };

  const handleAnswer = (isCorrect: boolean) => {
    if (gameState !== 'playing') return;

    if (isCorrect) {
      (window as any).correctAnswer();
    } else {
      (window as any).wrongAnswer();
    }
  };

  return (
    <div className="w-full flex flex-col md:flex-row gap-6 max-w-5xl mx-auto items-start relative">

      {/* Styles for Mascot Animation */}
      <style>{`
        @keyframes pop {
          from { transform: scale(0.8); opacity: 0; }
          to { transform: scale(1); opacity: 1; }
        }
        .mascot-pop {
          animation: pop 0.4s ease forwards;
        }
      `}</style>

      {/* Mascot Notification */}
      {mascot && (
        <div className="fixed bottom-6 right-6 z-50 bg-slate-900 text-white px-5 py-4 rounded-2xl shadow-2xl border border-slate-700 max-w-xs mascot-pop flex items-center gap-3 rtl:left-6 rtl:right-auto">
            <span className="text-3xl">{mascot.type === 'win' ? '🐻🍬' : '🐻💙'}</span>
            <div className="font-bold text-sm leading-tight">
                {mascot.text}
            </div>
        </div>
      )}

      {/* Candy Ladder */}
      <div className="w-full md:w-64 bg-slate-900 rounded-2xl p-4 border border-slate-700 shadow-xl shrink-0">
          <h4 className="text-yellow-400 font-bold text-center mb-4 flex items-center justify-center gap-2">
             <Candy className="w-4 h-4" /> {t.ladder}
          </h4>
          <div className="space-y-1.5 flex flex-col-reverse">
             {LEVELS.map((val, idx) => {
                 const isActive = idx === levelIndex;
                 const isSafe = SAFE_INDICES.includes(idx);
                 const isPassed = idx < levelIndex;

                 return (
                     <div 
                        key={idx}
                        className={`
                            relative text-center py-2 px-3 rounded-xl text-sm font-bold transition-all duration-300 flex items-center justify-between
                            ${isActive 
                                ? 'bg-yellow-500 text-black scale-105 shadow-lg z-10' 
                                : isPassed 
                                    ? 'bg-green-900/40 text-green-400 opacity-70' 
                                    : 'bg-slate-800 text-slate-500 opacity-60'
                            }
                            ${isSafe ? 'border-2 border-dashed border-white/20' : ''}
                        `}
                     >
                        <span className="w-5 flex justify-center">{isSafe && <Shield className="w-3 h-3" />}</span>
                        <span>{val} 🍬</span>
                        <span className="w-5 flex justify-center">{isActive && <ArrowRight className={`w-4 h-4 ${isAr ? 'rotate-180' : ''}`} />}</span>
                     </div>
                 )
             })}
          </div>
      </div>

      <div className="flex-1 w-full text-center space-y-6">
        <div className="mb-2">
            <h3 className="text-3xl font-bold mb-2 text-pink-400 flex items-center justify-center gap-2">
                <Candy className="w-8 h-8" />
                {t.title}
            </h3>
            <p className="text-slate-400 text-lg">{t.desc}</p>
        </div>

        <div className="bg-slate-800 p-8 rounded-3xl border-4 border-pink-400/30 shadow-2xl relative overflow-hidden min-h-[400px] flex flex-col justify-center">
            {/* Background Pattern */}
            <div className="absolute inset-0 opacity-5 pointer-events-none" 
                style={{ backgroundImage: 'radial-gradient(circle, #f472b6 2px, transparent 2px)', backgroundSize: '24px 24px' }}>
            </div>

            {/* Current Prize Mobile */}
            <div className="md:hidden absolute top-4 right-4 bg-slate-900/90 px-4 py-2 rounded-full border border-yellow-500/50 flex items-center gap-2 rtl:right-auto rtl:left-4 z-20">
                <Trophy className="w-4 h-4 text-yellow-400" />
                <span className="text-yellow-400 font-bold">{LEVELS[levelIndex]} 🍬</span>
            </div>

            {/* START STATE */}
            {gameState === 'start' && (
                <div className="py-10 animate-fade-in">
                    <div className="w-24 h-24 bg-slate-700/50 rounded-full flex items-center justify-center mx-auto mb-6">
                        <Candy className="w-12 h-12 text-pink-500 animate-bounce" />
                    </div>
                    <button 
                        onClick={loadQuestion}
                        className="px-10 py-4 bg-gradient-to-r from-pink-500 to-rose-500 hover:from-pink-400 hover:to-rose-400 text-white text-xl font-bold rounded-2xl shadow-lg transition-transform hover:scale-105"
                    >
                        {t.start}
                    </button>
                </div>
            )}

            {/* PLAYING STATE */}
            {gameState === 'playing' && (
                <div className="animate-fade-in relative z-10 w-full">
                    <div className="mb-8">
                         <span className="inline-block bg-slate-700/50 text-slate-300 px-3 py-1 rounded-full text-sm font-bold mb-4">
                             {isAr ? `المستوى ${levelIndex + 1}` : `Level ${levelIndex + 1}`}
                         </span>
                        <p className="text-2xl md:text-3xl font-bold text-white leading-relaxed max-w-2xl mx-auto">
                            {isAr ? QUESTIONS[currentQIndex].q.ar : QUESTIONS[currentQIndex].q.en}
                        </p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-2xl mx-auto">
                        {shuffledAnswers.map((ans, idx) => (
                            <button
                                key={idx}
                                onClick={() => handleAnswer(ans.c)}
                                className="w-full p-4 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded-xl transition-all border-2 border-transparent hover:border-pink-400 text-lg shadow-md active:scale-[0.98]"
                            >
                                {isAr ? ans.t.ar : ans.t.en}
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {/* FEEDBACK STATE */}
            {gameState === 'feedback' && (
                <div className="py-8 animate-fade-in relative z-10 flex flex-col items-center">
                    <CheckCircle className="w-24 h-24 text-green-400 mb-4 animate-[pop_0.5s_ease]" />
                    <h2 className="text-3xl font-bold text-green-400 mb-2">{t.correct}</h2>
                    <p className="text-slate-300 text-lg mb-8">
                        {isAr ? "انتقلت للمرحلة التالية!" : "Moved to next level!"}
                    </p>

                    <button 
                        onClick={loadQuestion}
                        className="px-10 py-4 bg-sky-500 hover:bg-sky-400 text-white font-bold rounded-2xl shadow-lg transition-transform hover:scale-105 flex items-center gap-2"
                    >
                        {t.next} 
                        {isAr ? <ArrowRight className="w-5 h-5 rotate-180" /> : <ArrowRight className="w-5 h-5" />}
                    </button>
                </div>
            )}

            {/* GAME OVER STATE */}
            {gameState === 'gameover' && (
                <div className="py-8 animate-fade-in relative z-10 flex flex-col items-center">
                    <XCircle className="w-24 h-24 text-red-400 mb-4 animate-[pop_0.5s_ease]" />
                    <h2 className="text-3xl font-bold text-red-400 mb-6">{t.gameOver}</h2>

                    <div className="bg-slate-900/80 p-6 rounded-2xl border border-yellow-500/30 mb-8 w-full max-w-sm">
                        <div className="text-slate-400 text-sm font-bold uppercase mb-2">{t.youWon}</div>
                        <div className="text-4xl font-black text-yellow-400 mb-2">
                             {safeCandy || LEVELS[0]} 🍬
                        </div>
                        <div className="text-xs text-slate-500">
                             {safeCandy > 0 ? (isAr ? "محمية بواسطة نقطة الأمان 🛡️" : "Secured by Safe Haven 🛡️") : (isAr ? "جائزة الترضية" : "Consolation Prize")}
                        </div>
                    </div>

                    <button 
                        onClick={restartGame}
                        className="px-10 py-4 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded-2xl shadow-lg transition-transform hover:scale-105 flex items-center gap-2"
                    >
                        {t.retry}
                    </button>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

