  const [mascot, setMascot] = useState<{type: 'win'|'lose', text: string} | null>(null);
  const mascotTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Audio
  const candySound = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    candySound.current = new Audio("https://assets.mixkit.co/sfx/preview/mixkit-game-success-alert-2039.mp3");
  }, []);

  const showMascot = (type: 'win' | 'lose') => {
    if (mascotTimeoutRef.current) clearTimeout(mascotTimeoutRef.current);

    const msgs = MESSAGES[type];
    const text = msgs[Math.floor(Math.random() * msgs.length)];

    setMascot({ type, text });

    mascotTimeoutRef.current = setTimeout(() => {
        setMascot(null);
    }, 4000);
  };

  const playWinSound = () => {
    if (candySound.current) {
        candySound.current.currentTime = 0;
        candySound.current.play().catch(e => console.log("Audio play blocked", e));
    }
  };

  // State Refs for window access
  const levelRef = useRef(levelIndex);
  const safeRef = useRef(safeCandy);

  useEffect(() => {
      levelRef.current = levelIndex;
      safeRef.current = safeCandy;
  }, [levelIndex, safeCandy]);

  // Global API Exposure
  useEffect(() => {
    (window as any).correctAnswer = () => {
        const currentLvl = levelRef.current;
        const nextLvl = currentLvl + 1;

        // Update Level
        if (nextLvl < LEVELS.length) {
            setLevelIndex(nextLvl);
            if (SAFE_INDICES.includes(nextLvl)) {
                setSafeCandy(LEVELS[nextLvl]);
            }
        } else {
             // Max level reached (Win Game)
             setLevelIndex(LEVELS.length - 1);
        }

        playWinSound();
        showMascot('win');

        // Advance UI
        setFeedback('correct');
        setGameState('feedback');
    };

    (window as any).wrongAnswer = () => {
        showMascot('lose');
        setFeedback('wrong');
        setGameState('gameover');
    };

