};

interface ReactionData {
  like: number;
  heart: number;
  names: string[];
}

export const ReadAndLearn: React.FC<Props> = ({ language, onBack }) => {
  const [selectedFact, setSelectedFact] = useState<typeof FACTS['English'][0] | null>(null);
  const [reactionData, setReactionData] = useState<ReactionData>({ like: 0, heart: 0, names: [] });

  const isAr = language === 'Arabic';
  const currentFacts = FACTS[language];

  const t = {
    title: isAr ? "اقرأ وتعلّم" : "Read & Learn",
    subtitle: isAr ? "معلومات سريعة وممتعة في أقل من دقيقة" : "Fun and quick facts in less than a minute",
    quickFact: isAr ? "اقرأ معلومة سريعة" : "Quick fact",
    gotIt: isAr ? "فهمت ✅" : "Got it ✅",
    back: isAr ? "العودة للقصص" : "Back to Stories",
    random: isAr ? "🎲 معلومة عشوائية" : "🎲 Random Fact",
    likedBy: isAr ? "أعجب بها:" : "Liked by:"
  };

  // Load reaction data when selectedFact changes
  useEffect(() => {
    if (selectedFact) {
        // Create a unique key for storage based on the title
        // We use a simple hash or just the string to keep it persistent
        const key = `sawan_react_${selectedFact.title.substring(0, 20)}`;
        try {
            const saved = localStorage.getItem(key);
            if (saved) {
                setReactionData(JSON.parse(saved));
            } else {
                setReactionData({ like: 0, heart: 0, names: [] });
            }
        } catch (e) {
            console.error("Failed to load reactions", e);
            setReactionData({ like: 0, heart: 0, names: [] });
        }
    }
  }, [selectedFact]);

  const handleRandomFact = () => {
    const random = currentFacts[Math.floor(Math.random() * currentFacts.length)];
    setSelectedFact(random);
  };

  const handleReaction = (type: 'like' | 'heart') => {
      if (!selectedFact) return;

      const namesList = REACTION_NAMES[language];
      const newData = { ...reactionData };

      // Increment count
      newData[type] = (newData[type] || 0) + 1;

      // Add a name if not recently added
      // Find a name that isn't in the current list if possible
      const availableNames = namesList.filter(n => !newData.names.includes(n));
      const nameToAdd = availableNames.length > 0 
          ? availableNames[Math.floor(Math.random() * availableNames.length)]
          : namesList[Math.floor(Math.random() * namesList.length)];

      // Add to beginning, keep max 5
      newData.names = [nameToAdd, ...newData.names].slice(0, 5);

      setReactionData(newData);

      const key = `sawan_react_${selectedFact.title.substring(0, 20)}`;
      localStorage.setItem(key, JSON.stringify(newData));
  };

  return (
