                            >
                                <Heart className="w-5 h-5 text-pink-400" fill="currentColor" />
                                <span>{reactionData.heart}</span>
                            </button>
                        </div>

                        {reactionData.names.length > 0 && (
                            <div className="text-sm text-slate-400">
                                <span className="font-bold text-slate-300">{t.likedBy}</span>
                                <div className="mt-1 flex flex-wrap gap-2">
                                    {reactionData.names.map((name, idx) => (
                                        <span key={idx} className="bg-slate-700/50 px-2 py-1 rounded text-xs text-slate-300">
                                            {name}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    <button 
                        onClick={() => setSelectedFact(null)}
                        className="w-full py-3 bg-emerald-500 hover:bg-emerald-400 text-black font-bold rounded-xl transition-colors shadow-lg active:scale-95 text-lg"
                    >
                        {t.gotIt}
                    </button>
                </div>
            </div>
        )}
    </div>
  );
};

