const REACTION_NAMES = {
  Arabic: ["⭐ طفل ذكي", "🌈 صديق فضولي", "🐻 مغامر صغير", "🦊 مفكر شاطر", "🐼 صديق لطيف", "🐯 بطل شجاع"],
  English: ["⭐ Smart Kid", "🌈 Curious Friend", "🐻 Little Adventurer", "🦊 Clever Thinker", "🐼 Kind Friend", "🐯 Brave Hero"]
};

interface ReactionData {
  like: number;
  heart: number;
  names: string[];
}

export const ReadAndLearn: React.FC<Props> = ({ language, onBack }) => {
  const [selectedFact, setSelectedFact] = useState<typeof FACTS['English'][0] | null>(null);
  const [reactionData, setReactionData] = useState<ReactionData>({ like: 0, heart: 0, names: [] });

  const isAr = language === 'Arabic';
  const currentFacts = FACTS[language];

  const t = {
    title: isAr ? "اقرأ وتعلّم" : "Read & Learn",
    subtitle: isAr ? "معلومات سريعة وممتعة في أقل من دقيقة" : "Fun and quick facts in less than a minute",
    quickFact: isAr ? "اقرأ معلومة سريعة" : "Quick fact",
    gotIt: isAr ? "فهمت ✅" : "Got it ✅",
    back: isAr ? "العودة للقصص" : "Back to Stories",
    random: isAr ? "🎲 معلومة عشوائية" : "🎲 Random Fact",
    likedBy: isAr ? "أعجب بها:" : "Liked by:"
  };

  // Load reaction data when selectedFact changes
  useEffect(() => {
    if (selectedFact) {
        // Create a unique key for storage based on the title (English title is stable if we map it, but here we just use the current title)
        // For better stability we could use index if array is static, but title is fine for MVP
        const key = `sawan_react_${selectedFact.title.replace(/\s+/g, '_').substring(0, 30)}`;
        try {
            const saved = localStorage.getItem(key);
            if (saved) {
                setReactionData(JSON.parse(saved));
            } else {
                setReactionData({ like: 0, heart: 0, names: [] });
            }
        } catch (e) {
            console.error("Failed to load reactions", e);
            setReactionData({ like: 0, heart: 0, names: [] });
        }
    }
  }, [selectedFact]);

  const handleRandomFact = () => {
    const random = currentFacts[Math.floor(Math.random() * currentFacts.length)];
    setSelectedFact(random);
  };

  const handleReaction = (type: 'like' | 'heart') => {
      if (!selectedFact) return;

      const namesList = REACTION_NAMES[language];
      const newData = { ...reactionData };

      // Increment count
      newData[type] = (newData[type] || 0) + 1;

      // Add a name if not recently added
      const availableNames = namesList.filter(n => !newData.names.includes(n));
      const nameToAdd = availableNames.length > 0 
          ? availableNames[Math.floor(Math.random() * availableNames.length)]
          : namesList[Math.floor(Math.random() * namesList.length)];

      // Add to beginning, keep max 3 (as per script requirement)
      newData.names = [nameToAdd, ...newData.names].slice(0, 3);

      setReactionData(newData);

      const key = `sawan_react_${selectedFact.title.replace(/\s+/g, '_').substring(0, 30)}`;
      localStorage.setItem(key, JSON.stringify(newData));
  };

  return (
    <div className="w-full max-w-6xl mx-auto p-6 animate-fade-in flex-1 flex flex-col items-center">

        {/* Navigation Header */}
        <div className="w-full flex justify-start mb-4">
             <button 
                onClick={onBack}
                className="px-6 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 font-bold rounded-xl transition-colors inline-flex items-center gap-2 border border-slate-700"
            >
                {isAr ? <ArrowRight className="w-5 h-5"/> : <ArrowLeft className="w-5 h-5"/>}
                {t.back}
            </button>
        </div>

        <div className="text-center mb-12">
            <h1 className="text-3xl md:text-5xl font-heading font-bold text-white mb-4 flex items-center justify-center gap-4">
                <BookOpen className="w-12 h-12 text-emerald-400" />
                {t.title}
            </h1>
            <p className="text-slate-400 text-lg md:text-xl font-medium max-w-2xl mx-auto">{t.subtitle}</p>

            <button 
                onClick={handleRandomFact}
                className="mt-6 px-6 py-3 bg-gradient-to-r from-green-500 to-emerald-500 hover:from-green-400 hover:to-emerald-400 text-black font-extrabold text-lg rounded-2xl shadow-lg hover:scale-105 transition-all flex items-center gap-2 mx-auto"
            >
                {t.random}
            </button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6 w-full">
            {currentFacts.map((item, idx) => (
                <div 
                    key={idx}
                    onClick={() => setSelectedFact(item)}
                    className="bg-slate-800 p-6 rounded-[24px] cursor-pointer hover:bg-slate-700 hover:-translate-y-2 transition-all border-2 border-slate-700 hover:border-emerald-500/50 shadow-xl group flex flex-col items-start h-full"
                >
                    <div className="bg-slate-900/50 p-3 rounded-full mb-4 group-hover:scale-110 transition-transform">
                        <BookOpen className="w-6 h-6 text-emerald-500" />
                    </div>
                    <h4 className="font-bold text-white mb-auto group-hover:text-emerald-300 transition-colors text-xl leading-snug">{item.title}</h4>
                    <div className="w-full mt-4 pt-4 border-t border-slate-700/50 flex justify-between items-center">
                        <small className="text-slate-500 font-bold text-xs uppercase tracking-wider">{t.quickFact}</small>
                        <span className="text-emerald-500 opacity-0 group-hover:opacity-100 transition-opacity transform translate-x-2 group-hover:translate-x-0">
                            {isAr ? <ArrowLeft className="w-4 h-4" /> : <ArrowRight className="w-4 h-4" />}
                        </span>
                    </div>
                </div>
            ))}
        </div>

        {selectedFact && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-fade-in" onClick={() => setSelectedFact(null)}>
                <div className="bg-slate-900 border border-slate-700 p-8 rounded-3xl max-w-md w-full relative shadow-2xl transform transition-all scale-100" onClick={e => e.stopPropagation()}>
                    <button 
                        onClick={() => setSelectedFact(null)}
                        className="absolute top-4 right-4 text-slate-400 hover:text-white rtl:left-4 rtl:right-auto"
                    >
                        <X className="w-6 h-6" />
                    </button>
                    <div className="flex items-center gap-3 mb-6 border-b border-slate-800 pb-4">
                        <span className="text-3xl">💡</span>
                        <h3 className="text-2xl font-bold text-emerald-400">{selectedFact.title}</h3>
                    </div>
                    <p className="text-lg text-slate-200 leading-relaxed mb-8 font-medium">{selectedFact.text}</p>

                    {/* Reactions Section */}
                    <div className="bg-slate-800/50 rounded-xl p-4 mb-8 border border-slate-700 mt-4">
                        <div className="flex items-center gap-4 mb-4">
                            <button 
                                onClick={() => handleReaction('like')}
                                className="flex items-center gap-2 px-4 py-2 bg-slate-700 hover:bg-slate-600 rounded-lg text-white font-bold transition-all hover:scale-105 active:scale-95 border border-slate-600"
                            >
                                <ThumbsUp className="w-5 h-5 text-blue-400" />
                                <span>{reactionData.like}</span>
                            </button>
                            <button 
                                onClick={() => handleReaction('heart')}
                                className="flex items-center gap-2 px-4 py-2 bg-slate-700 hover:bg-slate-600 rounded-lg text-white font-bold transition-all hover:scale-105 active:scale-95 border border-slate-600"
                            >
                                <Heart className="w-5 h-5 text-pink-400" fill="currentColor" />
                                <span>{reactionData.heart}</span>
                            </button>
                        </div>

                        {reactionData.names.length > 0 && (
                            <div className="text-sm text-slate-400">
                                <span className="font-bold text-slate-300 block mb-2">{t.likedBy}</span>
                                <div className="flex flex-wrap gap-2">
                                    {reactionData.names.map((name, idx) => (
                                        <span key={idx} className="bg-slate-700/50 px-2 py-1 rounded text-xs text-slate-300 border border-slate-600">
                                            {name}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        )}
                    </div>

                    <button 
                        onClick={() => setSelectedFact(null)}
                        className="w-full py-3 bg-emerald-500 hover:bg-emerald-400 text-black font-bold rounded-xl transition-colors shadow-lg active:scale-95 text-lg"
                    >
                        {t.gotIt}
                    </button>
                </div>
            </div>
        )}
    </div>
  );
};

