                    </div>
                    <h3 className="text-xl font-bold text-white text-center mb-2">{t.meaning}</h3>
                    <p className="text-slate-300 text-center leading-relaxed flex-1">{result.meaning}</p>
                    <button 
                        onClick={() => handleSpeak(result.meaning)}
                        className="mt-4 mx-auto p-2 bg-slate-800 hover:bg-slate-700 rounded-full text-blue-400 transition-colors hover:scale-110 active:scale-95"
                        title={isAr ? "استمع" : "Listen"}
                    >
